# Once a round has a verified three-floor group, foreground recovery is a
# translation-tracking problem, not another map-alignment problem.  The player
# commonly closes the map inside two seconds, so a locked round may never enter
# the exhaustive selected-map fitter on the foreground path.
LOCKED_ROUND_RECOVERY_BUDGET_MS = 1500.0
CURRENT_FLOOR_RELOCALIZATION_TARGET_MS = 1000.0
CURRENT_FLOOR_RELOCALIZATION_HARD_LIMIT_MS = 1000.0
# A verified same-floor reopen may need one settled current-frame correction.
# This wider window is deliberately selected at the locked round-group entry,
# never for first identity, member switching, B1, or cross-floor recovery.
LOCKED_SAME_FLOOR_REOPEN_HARD_LIMIT_MS = 3000.0
LOCKED_SAME_FLOOR_REOPEN_RELAXED_MAXIMUM_TRANSLATION_PIXELS = 240.0
LOCKED_ROUND_WIDE_TRANSLATION_MAXIMUM_PIXELS = 960.0
# Three points are enough for a bounded translation decision, but not enough
# to carry a rolling pool across a close/reopen edge without making the next
# optical-flow result brittle.  This is a pool-continuity guard, not a change
# to AlignmentCoreV2's candidate authorization minimum.
RECOVERY_ANCHOR_MIN_POOL_SIZE = 4
LARGE_SHARED_ROOT_TRANSLATION_PIXELS = 180.0
MINIMUM_WIDE_TRANSLATION_DISTINCT_MARGIN = 0.015
# Visual probes arrive while the game map is still fading/centering into its
# settled viewport.  A restored or freshly corrected overlay owns the pose
# during this interval; only the independent physical-drag path may move it.
MAP_POSE_VISUAL_SETTLE_SECONDS = 0.85
# A committed cross-floor correction can be large enough that the next map
# reopen's phase sensor sees the exact inverse as a camera move.  Keep a
# short-lived, vector-specific guard for that presentation-only artifact.  It
# is deliberately narrow: physical mouse-drag prediction and multi-anchor
# motion remain untouched, and a different vector is never suppressed.
POST_CORRECTION_INVERSE_GUARD_SECONDS = 8.0
POST_CORRECTION_INVERSE_GUARD_MAX_HITS = 6
POST_CORRECTION_INVERSE_MIN_SHIFT_PIXELS = 96.0
POST_CORRECTION_INVERSE_RELATIVE_TOLERANCE = 0.12
# First-use identity must never run the 13-map fine aligner in the foreground.
# Leave 150 ms for event delivery/UI rendering before the 2 s product cutoff.
AUTO_IDENTITY_BUDGET_SECONDS = 1.85


def same_floor_locked_reopen_hard_limit_ms(relaxed: bool) -> float:
    """Return the hard display cutoff for one eligible same-floor reopen."""
    return (
        LOCKED_SAME_FLOOR_REOPEN_HARD_LIMIT_MS
        if bool(relaxed) else CURRENT_FLOOR_RELOCALIZATION_HARD_LIMIT_MS
    )


def same_floor_locked_reopen_budget_allows(
    elapsed_ms: float,
    *,
    relaxed: bool,
) -> bool:
    """Keep the reopen cutoff finite and exclusive to the selected tier."""
    try:
        elapsed = float(elapsed_ms)
    except (TypeError, ValueError):
        return False
    return bool(
        math.isfinite(elapsed)
        and elapsed >= 0.0
        and elapsed <= same_floor_locked_reopen_hard_limit_ms(relaxed)
    )


def load_b1_f1_layer_relations(path: Path = B1_F1_LAYER_RELATIONS_PATH) -> dict[str, np.ndarray]:
    try:
        raw = json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError):
        return {}
    policy = raw.get("policy") or {}
    if not (
        raw.get("schema") == "identityv-nightmare-b1-f1-layer-relations-v1"
        and policy.get("candidateOnly") is True
        and policy.get("requiresCurrentFrameValidation") is True
        and policy.get("authorizesDirectDisplay") is False
        and policy.get("singleSharedRuntimePose") is True
    ):
        return {}
    relations = {}
    for map_id, value in (raw.get("maps") or {}).items():
        matrix = np.asarray(value, dtype=np.float64)
        if (
            matrix.shape == (3, 3) and np.isfinite(matrix).all()
            and abs(float(np.linalg.det(matrix[:2, :2]))) > 1e-9
        ):
            relations[str(map_id)] = matrix
    return relations


B1_F1_LAYER_RELATIONS: dict[str, np.ndarray] | None = None


def build_fingerprint(paths: tuple[Path, ...] | None = None) -> str:
    """Return the source fingerprint captured by this running process.

    A process keeps this value from startup.  If files are edited while an old
    assistant is still alive, its visible fingerprint therefore remains old
    and cannot be mistaken for the newly tested source checkout.
    """
    # PyInstaller does not ship the entry-point .py files as ordinary files.
    # A frozen process must therefore use the source fingerprint embedded by
    # the release builder instead of hashing a set of "missing:<name>" values.
    if paths is None and getattr(sys, "frozen", False):
        embedded_path = RESOURCE_ROOT / "references" / "build-fingerprint.txt"
        try:
            embedded = embedded_path.read_text(encoding="ascii").strip().upper()
        except OSError:
            embedded = ""
        if re.fullmatch(r"[0-9A-F]{8}", embedded):
            return embedded

    sources = paths or (
        *sorted((SOURCE_ROOT / "app").glob("*.py"), key=lambda path: path.name),
        (RESOURCE_ROOT / "references" / "nightmare-front-door-identities.json").resolve(),
        (RESOURCE_ROOT / "references" / "nightmare-front-door-clean-previews.json").resolve(),
        (RESOURCE_ROOT / "references" / "nightmare-canonical-coordinate-pack.json").resolve(),
        (RESOURCE_ROOT / "references" / "nightmare-author-route-catalog.json").resolve(),
        (RESOURCE_ROOT / "references" / "nightmare-author-structure-index.json").resolve(),
        B1_F1_LAYER_RELATIONS_PATH.resolve(),
        PORTABLE_LAYOUT_SEEDS_PATH.resolve(),
        (RESOURCE_ROOT / "references" / "identityv-assistant.manifest").resolve(),
        (ROOT / "version.json").resolve(),
        (ROOT / "start_identityv_assistant.ps1").resolve(),
        (ROOT / "work" / "build_daily_release.ps1").resolve(),
    )
    digest = hashlib.sha256()
    for path in sources:
        try:
            content = path.read_bytes()
        except OSError:
            content = f"missing:{path.name}".encode("utf-8", errors="replace")
        digest.update(path.name.encode("utf-8", errors="replace"))
        digest.update(b"\0")
        digest.update(content)
        digest.update(b"\0")
    return digest.hexdigest()[:8].upper()


BUILD_FINGERPRINT = build_fingerprint()

VALIDATED_CLIENT_RESOLUTIONS = {
    "1080p": (1920, 1080),
    "1440p": (2560, 1440),
}
VALIDATED_WINDOWS_SCALE_PERCENTS = (100, 125, 150)
DPI_AWARENESS_MODE = "not-requested"


def enable_per_monitor_dpi_awareness() -> str:
    """Request physical-pixel coordinates without changing any Windows setting."""
    if os.name != "nt":
        return "non-windows"
    try:
        setter = ctypes.windll.user32.SetProcessDpiAwarenessContext
        setter.argtypes = [ctypes.c_void_p]
        setter.restype = ctypes.c_bool
        if setter(ctypes.c_void_p(-4)):  # DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2
            return "per-monitor-v2"
    except (AttributeError, OSError, TypeError, ValueError):
        pass
    try:
        setter = ctypes.windll.shcore.SetProcessDpiAwareness
        setter.argtypes = [ctypes.c_int]
        setter.restype = ctypes.c_long
        result = int(setter(2))  # PROCESS_PER_MONITOR_DPI_AWARE
        if result == 0:
            return "per-monitor"
        if result & 0xFFFFFFFF == 0x80070005:
            return "already-configured"
    except (AttributeError, OSError, TypeError, ValueError):
        pass
    try:
        if ctypes.windll.user32.SetProcessDPIAware():
            return "system-aware-fallback"
    except (AttributeError, OSError):
        pass
    return "windows-default"


def window_dpi(hwnd: int | None) -> int:
    if os.name != "nt":
        return 96
    if hwnd:
        try:
            getter = ctypes.windll.user32.GetDpiForWindow
            getter.argtypes = [ctypes.c_void_p]
            getter.restype = ctypes.c_uint
            value = int(getter(hwnd))
            if value > 0:
                return value
        except (AttributeError, OSError, TypeError, ValueError):
            pass
    try:
        getter = ctypes.windll.user32.GetDpiForSystem
        getter.restype = ctypes.c_uint
        value = int(getter())
        if value > 0:
            return value
    except (AttributeError, OSError, TypeError, ValueError):
        pass
    return 96


if os.name == "nt":
    # ctypes caches pointer and callback types strongly. Reuse their types,
    # while each enumeration still owns fresh callback/data instances.
    class _MonitorNativeRect(ctypes.Structure):
        _fields_ = [
            ("left", ctypes.c_long), ("top", ctypes.c_long),
            ("right", ctypes.c_long), ("bottom", ctypes.c_long),
        ]

    class _MonitorInfoEx(ctypes.Structure):
        _fields_ = [
            ("cbSize", wintypes.DWORD),
            ("rcMonitor", _MonitorNativeRect),
            ("rcWork", _MonitorNativeRect),
            ("dwFlags", wintypes.DWORD),
            ("szDevice", wintypes.WCHAR * 32),
        ]

    _MonitorEnumCallback = ctypes.WINFUNCTYPE(
        wintypes.BOOL, wintypes.HMONITOR, wintypes.HDC,
        ctypes.POINTER(_MonitorNativeRect), wintypes.LPARAM,
    )


def enumerate_monitor_contexts() -> tuple[MonitorContext, ...]:
    """Read physical monitor bounds, work areas, identities and runtime DPI."""

    if os.name != "nt":
        return (
            MonitorContext(
                monitor_id="primary",
                bounds_px=RectPx(0, 0, 1920, 1080),
                work_area_px=RectPx(0, 0, 1920, 1040),
                dpi=96,
                is_primary=True,
            ),
        )

    rows: list[MonitorContext] = []

    def callback(monitor, _dc, _rect, _data):
        info = _MonitorInfoEx()
        info.cbSize = ctypes.sizeof(_MonitorInfoEx)
        if not ctypes.windll.user32.GetMonitorInfoW(monitor, ctypes.byref(info)):
            return True
        dpi_value = 96
        try:
            x_dpi = ctypes.c_uint()
            y_dpi = ctypes.c_uint()
            if int(ctypes.windll.shcore.GetDpiForMonitor(
                monitor, 0, ctypes.byref(x_dpi), ctypes.byref(y_dpi),
            )) == 0:
                dpi_value = max(1, int(x_dpi.value))
        except Exception:
            dpi_value = 96
        bounds = RectPx(
            int(info.rcMonitor.left), int(info.rcMonitor.top),
            int(info.rcMonitor.right), int(info.rcMonitor.bottom),
        )
        work = RectPx(
            int(info.rcWork.left), int(info.rcWork.top),
            int(info.rcWork.right), int(info.rcWork.bottom),
        )
        rows.append(MonitorContext(
            monitor_id=str(info.szDevice or f"monitor-{len(rows)}"),
            bounds_px=bounds,
            work_area_px=work,
            dpi=dpi_value,
            is_primary=bool(int(info.dwFlags) & 1),
        ))
        return True

    try:
        ctypes.windll.user32.EnumDisplayMonitors(
            None, None, _MonitorEnumCallback(callback), 0,
        )
    except Exception:
        rows = []
    if rows:
        return tuple(rows)
    width = max(1, int(ctypes.windll.user32.GetSystemMetrics(0) or 1920))
    height = max(1, int(ctypes.windll.user32.GetSystemMetrics(1) or 1080))
    return (
        MonitorContext(
            monitor_id="primary-fallback",
            bounds_px=RectPx(0, 0, width, height),
            work_area_px=RectPx(0, 0, width, height),
            dpi=96,
            is_primary=True,
        ),
    )


def classify_display_environment(
    client_width: int,
    client_height: int,
    dpi: int,
    *,
    window_mode: str = "unknown",
    monitor_count: int = 1,
    dpi_awareness: str = "unknown",
    client_origin: tuple[int, int] = (0, 0),
    monitor_id: str = "unknown",
    monitor_bounds: tuple[int, int, int, int] | None = None,
    monitor_work_area: tuple[int, int, int, int] | None = None,
    topology_signature: tuple = (),
) -> dict:
    """Classify tested display ranges without blocking unfamiliar environments."""
    width = max(0, int(client_width))
    height = max(0, int(client_height))
    dpi_value = max(1, int(dpi or 96))
    scale_percent = int(round(dpi_value * 100.0 / 96.0))
    resolution_class = None
    for label, (target_width, target_height) in VALIDATED_CLIENT_RESOLUTIONS.items():
        width_ok = abs(width - target_width) <= max(24, round(target_width * 0.025))
        # Windowed/borderless clients can lose a small title/taskbar strip.
        height_ok = abs(height - target_height) <= max(32, round(target_height * 0.04))
        if width_ok and height_ok:
            resolution_class = label
            break
    nearest_scale = min(
        VALIDATED_WINDOWS_SCALE_PERCENTS,
        key=lambda candidate: abs(scale_percent - candidate),
    )
    scale_class = nearest_scale if abs(scale_percent - nearest_scale) <= 2 else None
    reasons = []
    if resolution_class is None:
        reasons.append("client-resolution-outside-verified-range")
    if scale_class is None:
        reasons.append("windows-scale-outside-verified-range")
    verified = not reasons
    dimensions = f"{width}×{height}" if width and height else "尺寸读取失败"
    if verified:
        user_message = f"显示环境：{dimensions} · {scale_percent}% · 已验证自动适配"
    else:
        user_message = (
            f"显示环境：{dimensions} · {scale_percent}% 超出已验证范围；"
            "已继续自动适配并记录，无需修改系统设置"
        )
    return {
        "clientOrigin": [int(client_origin[0]), int(client_origin[1])],
        "clientBounds": [
            int(client_origin[0]), int(client_origin[1]),
            int(client_origin[0]) + width, int(client_origin[1]) + height,
        ],
        "clientWidth": width,
        "clientHeight": height,
        "clientAspect": round(width / height, 4) if height else None,
        "dpi": dpi_value,
        "scalePercent": scale_percent,
        "resolutionClass": resolution_class,
        "scaleClass": f"{scale_class}%" if scale_class else None,
        "windowMode": str(window_mode),
        "monitorCount": max(1, int(monitor_count or 1)),
        "monitorId": str(monitor_id or "unknown"),
        "monitorBounds": list(monitor_bounds or (0, 0, width, height)),
        "monitorWorkArea": list(monitor_work_area or (0, 0, width, height)),
        "topologySignature": tuple(topology_signature),
        "dpiAwareness": str(dpi_awareness),
        "verifiedCommonRange": verified,
        "reasons": reasons,
        "userMessage": user_message,
        "adaptationPolicy": (
            "continue-with-normalized-client-geometry-and-current-frame-validation;"
            "never-request-system-setting-change"
        ),
    }


def display_environment_signature(environment: dict | None) -> tuple:
    value = environment or {}
    origin = value.get("clientOrigin") or (0, 0)
    work_area = value.get("monitorWorkArea") or (0, 0, 0, 0)
    return client_geometry_signature(
        origin=(int(origin[0]), int(origin[1])),
        size=(
            int(value.get("clientWidth") or 0),
            int(value.get("clientHeight") or 0),
        ),
        dpi=int(value.get("dpi") or 0),
        window_mode=str(value.get("windowMode") or "unknown"),
        monitor_id=str(value.get("monitorId") or "unknown"),
        work_area=tuple(int(item) for item in work_area),
        topology_signature=tuple(value.get("topologySignature") or ()),
    )


def inspect_display_environment(hwnd: int | None) -> dict:
    left = top = width = height = 0
    window_mode = "unknown"
    error = None
    try:
        left, top, right, bottom = client_rect(int(hwnd))
        width, height = max(0, right - left), max(0, bottom - top)
        class Rect(ctypes.Structure):
            _fields_ = [
                ("left", ctypes.c_long), ("top", ctypes.c_long),
                ("right", ctypes.c_long), ("bottom", ctypes.c_long),
            ]
        rect = Rect()
        if ctypes.windll.user32.GetWindowRect(hwnd, ctypes.byref(rect)):
            frame_width = max(0, int(rect.right - rect.left))
            frame_height = max(0, int(rect.bottom - rect.top))
            window_mode = (
                "borderless-or-fullscreen"
                if abs(frame_width - width) <= 8 and abs(frame_height - height) <= 8
                else "windowed"
            )
    except Exception as exception:
        error = f"{type(exception).__name__}: {exception}"
    monitors = enumerate_monitor_contexts()
    client_bounds = RectPx(
        int(left), int(top), int(left) + max(1, width), int(top) + max(1, height),
    )
    monitor = select_monitor_for_rect(client_bounds, monitors)
    topology = monitor_topology_signature(monitors)
    monitor_count = len(monitors)
    environment = classify_display_environment(
        width, height, window_dpi(hwnd), window_mode=window_mode,
        monitor_count=monitor_count, dpi_awareness=DPI_AWARENESS_MODE,
        client_origin=(int(left), int(top)),
        monitor_id=monitor.monitor_id,
        monitor_bounds=monitor.bounds_px.as_tuple(),
        monitor_work_area=monitor.work_area_px.as_tuple(),
        topology_signature=topology,
    )
    if error:
        environment["inspectionError"] = error
    try:
        version = sys.getwindowsversion()
        environment["windowsVersion"] = (
            f"{version.major}.{version.minor}.{version.build}"
        )
    except AttributeError:
        environment["windowsVersion"] = "unknown"
    return environment


def normalize_route_profile_id(value) -> str:
    candidate = str(value or "").strip()
    if gallery_of(candidate):
        return candidate  # A custom map gallery; availability is checked where it is used.
    return candidate if candidate in ROUTE_PROFILE_LABELS or candidate == SHARED_STRUCTURE_PROFILE_ID else DEFAULT_ROUTE_PROFILE_ID


def same_map_round_group_can_be_preserved(
    group,
    previous_confirmation: dict | None,
    map_id: str,
    route_profile_id: str,
) -> bool:
    """Keep only a same-map/profile pose as a revalidation candidate."""
    return bool(
        isinstance(group, RoundLayerGroup)
        and group.map_id == map_id
        and (previous_confirmation or {}).get("mapId") == map_id
        and group.route_profile_id == normalize_route_profile_id(route_profile_id)
    )


def normalize_persisted_active_confirmation(
    remembered,
    valid_map_ids,
) -> dict | None:
    """Keep a remembered map identity but retire legacy permanent floor locks."""
    if not (
        isinstance(remembered, dict)
        and remembered.get("mapId") in set(valid_map_ids)
        and remembered.get("floor") in {"1", "2", "B1"}
    ):
        return None
    return {
        **remembered,
        # ``locked`` and the older ``manual`` mode both predate automatic
        # cross-floor tracking. The floor remains only a reopen seed; every
        # new map frame owns the actual floor decision.
        "floorMode": "auto",
    }


def normalize_coffin_variant_id(value) -> str:
    candidate = str(value or "").strip()
    return candidate if candidate in COFFIN_VARIANT_LABELS else COFFIN_VARIANT_OPTIONS[0][0]


class CursorPoint(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]


def cursor_screen_position() -> tuple[int, int] | None:
    """Read the cursor without intercepting, forwarding, or injecting input."""
    point = CursorPoint()
    if not ctypes.windll.user32.GetCursorPos(ctypes.byref(point)):
        return None
    return int(point.x), int(point.y)


def translated_source_matrix(
    matrix_source_to_client: list[list[float]] | np.ndarray | None,
    dx: float,
    dy: float,
) -> np.ndarray | None:
    """Apply a client-space pan to an original-sheet transform."""
    if matrix_source_to_client is None:
        return None
    matrix = np.asarray(matrix_source_to_client, dtype=np.float64)
    if matrix.shape != (3, 3) or not np.isfinite(matrix).all():
        return None
    translated = matrix.copy()
    translated[0, 2] += float(dx)
    translated[1, 2] += float(dy)
    return translated


DEFAULT_DRAG_BOUNDARY_NORMALIZED = (0.08, 0.13, 0.94, 0.94)


def normalize_drag_boundary(value) -> tuple[float, float, float, float] | None:
    """Validate one resolution-independent client-area interaction boundary."""
    if not isinstance(value, (list, tuple)) or len(value) != 4:
        return None
    try:
        normalized = tuple(float(item) for item in value)
    except (TypeError, ValueError):
        return None
    if not np.isfinite(normalized).all():
        return None
    left, top, right, bottom = normalized
    if not (
        0.0 <= left < right <= 1.0
        and 0.0 <= top < bottom <= 1.0
        and right - left >= 0.15
        and bottom - top >= 0.15
    ):
        return None
    return left, top, right, bottom


def drag_boundary_client_rect(
    client_bounds,
    normalized_boundary,
) -> tuple[float, float, float, float] | None:
    """Project a normalized boundary into the current game client rectangle."""
    boundary = normalize_drag_boundary(normalized_boundary)
    if boundary is None or not client_bounds:
        return None
    left, top, right, bottom = (int(value) for value in client_bounds)
    width, height = right - left, bottom - top
    if width < 100 or height < 100:
        return None
    x1, y1, x2, y2 = boundary
    return (
        left + width * x1,
        top + height * y1,
        left + width * x2,
        top + height * y2,
    )


def normalized_drag_boundary_from_rect(
    rectangle,
    client_size,
) -> tuple[float, float, float, float] | None:
    """Convert an edited client-local rectangle into persistent ratios."""
    if not isinstance(rectangle, (list, tuple)) or len(rectangle) != 4:
        return None
    if not isinstance(client_size, (list, tuple)) or len(client_size) != 2:
        return None
    try:
        width, height = (float(value) for value in client_size)
        x1, y1, x2, y2 = (float(value) for value in rectangle)
    except (TypeError, ValueError):
        return None
    if width <= 0.0 or height <= 0.0:
        return None
    return normalize_drag_boundary((x1 / width, y1 / height, x2 / width, y2 / height))


def cursor_can_drag_visible_map(
    cursor: tuple[int, int] | None,
    client_bounds,
    component: dict | None,
    normalized_boundary=None,
) -> bool:
    """Allow drag mirroring anywhere on the game map canvas, not just walls.

    A newly entered floor can be almost entirely fogged, and players commonly
    begin a drag in that empty area. Requiring the press to fall inside the
    currently explored component silently disabled the exact cross-floor drag
    case the layer group is meant to support. Fixed HUD/control strips remain
    excluded and a zero-motion click is discarded at mouse-up.
    """
    if cursor is None or not client_bounds:
        return False
    left, top, right, bottom = (int(value) for value in client_bounds)
    width, height = right - left, bottom - top
    if width < 100 or height < 100:
        return False
    calibrated_rect = drag_boundary_client_rect(
        client_bounds, normalized_boundary,
    )
    if calibrated_rect is not None:
        x1, y1, x2, y2 = calibrated_rect
        return bool(x1 <= cursor[0] < x2 and y1 <= cursor[1] < y2)
    client_x, client_y = cursor[0] - left, cursor[1] - top
    fixed_control = (
        client_y <= height * 0.13
        or client_x <= width * 0.08
        or client_x >= width * 0.94
        or client_y >= height * 0.94
    )
    inside_client = 0 <= client_x < width and 0 <= client_y < height
    return bool(inside_client and not fixed_control)


def calibrated_drag_motion_policy(
    cursor: tuple[int, int] | None,
    client_bounds,
    normalized_boundary,
    previously_allowed: bool,
) -> tuple[bool, bool]:
    """Return (record_delta, current_allowed) for one held-mouse sample.

    With no calibration this deliberately returns the legacy behavior: every
    held movement is recorded after an eligible press. With calibration,
    leaving the rectangle pauses prediction and the first sample after re-entry
    only re-arms the origin, preventing a large catch-up jump.
    """
    boundary = normalize_drag_boundary(normalized_boundary)
    if boundary is None:
        return True, True
    current_allowed = cursor_can_drag_visible_map(
        cursor, client_bounds, None, boundary,
    )
    return bool(previously_allowed and current_allowed), current_allowed


def cursor_is_map_close_control(
    cursor: tuple[int, int] | None,
    client_bounds,
) -> bool:
    """Recognize a physical click on the map's fixed top-right close area."""
    if cursor is None or not client_bounds:
        return False
    left, top, right, bottom = (int(value) for value in client_bounds)
    width, height = right - left, bottom - top
    if width < 100 or height < 100:
        return False
    client_x, client_y = cursor[0] - left, cursor[1] - top
    return bool(
        width * 0.90 <= client_x < width
        and 0 <= client_y <= height * 0.22
    )


def game_floor_control_hit(
    cursor: tuple[int, int] | None,
    client_bounds,
    floor_read: dict | None,
) -> int | None:
    """Return the game floor button under a click, only for localized HUDs."""
    if cursor is None or not client_bounds or not isinstance(floor_read, dict):
        return None
    difficult=floor_read.get('layout')=='difficult-two-buttons'
    if floor_read.get("layout") != "localized-triplet" and not difficult:
        return None
    centers = floor_read.get("centers")
    if not isinstance(centers, (list, tuple)) or len(centers) != (2 if difficult else 3):
        return None
    left, top, right, bottom = (int(value) for value in client_bounds)
    width, height = right - left, bottom - top
    if width < 100 or height < 100:
        return None
    if difficult:
        observation = floor_read.get('difficultObservation') or {}
        if observation.get('mapOpen') is not True:
            return None
        glyphs = observation.get('glyphs') or []
        try:
            points = np.asarray([g['center'] for g in glyphs], dtype=float)
            sx, sy = map(float, observation.get('controlScale', (1., 1.)))
        except (KeyError, ValueError, TypeError):
            return None
        if points.shape != (2, 2) or not np.isfinite(points).all() or not (np.isfinite([sx, sy]).all() and sx > 0 and sy > 0):
            return None
        spacing = float(points[1, 0] - points[0, 0])
        if spacing <= 0:
            return None
        px, py = cursor[0] - left, cursor[1] - top
        # Native glyph positions own hit geometry. Adjacent buttons meet at
        # their midpoint instead of overlapping a fixed client-width strip.
        index = 0 if px < float(points[:, 0].mean()) else 1
        cx, cy = points[index]
        if abs(px - cx) <= min(64. * sx, spacing / 2.) and abs(py - cy) <= 22. * sy:
            return index + 1
        return None
    vertical = floor_control_vertical_geometry(width, height)
    region_top = float(vertical.get("regionTop", 0.0))
    region_height = float(vertical.get("regionHeight", 0.0))
    x = (cursor[0] - left) / width
    y = (cursor[1] - top) / height
    if not (region_top <= y <= region_top + region_height):
        return None
    for floor, center in zip((1,2) if difficult else (-1, 1, 2), centers):
        if abs(x - float(center)) <= 0.025:
            return floor
    return None


def report_unhandled_error(exc_type, exc_value, exc_traceback) -> None:
    """Keep pythonw failures actionable without leaving a console window."""
    try:
        LIVE_ROOT.mkdir(parents=True, exist_ok=True)
        path = LIVE_ROOT / f"startup-error-{datetime.now():%Y%m%d-%H%M%S}.log"
        path.write_text(
            "".join(traceback.format_exception(exc_type, exc_value, exc_traceback)),
            encoding="utf-8",
        )
        message = f"星图遇到错误，已保存诊断日志：\n{path}"
    except OSError:
        message = f"星图遇到错误：\n{exc_value}"
    try:
        ctypes.windll.user32.MessageBoxW(None, message, "星图", 0x10)
    except Exception:
        pass


def atomic_write_text(path: Path, text: str) -> None:
    """Durably replace a small state file without exposing a partial JSON."""
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    try:
        with temporary.open("w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


DIAGNOSTIC_LOG_LIMIT = 8
DIAGNOSTIC_FILE_BYTE_LIMIT = 8 * 1024 * 1024
DIAGNOSTIC_TOTAL_BYTE_LIMIT = 24 * 1024 * 1024


INTEGRITY_LEVEL_RANKS = {
    "Untrusted": 0,
    "Low": 1,
    "Medium": 2,
    "MediumPlus": 3,
    "High": 4,
    "System": 5,
}


def integrity_level_from_rid(rid: int) -> str:
    """Convert the final mandatory-label SID component to a safe name."""
    value = int(rid)
    if value >= 0x4000:
        return "System"
    if value >= 0x3000:
        return "High"
    if value >= 0x2100:
        return "MediumPlus"
    if value >= 0x2000:
        return "Medium"
    if value >= 0x1000:
        return "Low"
    return "Untrusted"


def hotkey_read_permission_expected(
    assistant_integrity: dict | None,
    game_integrity: dict | None,
) -> bool:
    """Only claim expected access when both labels are known and sufficient."""
    try:
        assistant_rank = int((assistant_integrity or {}).get("rank", -1))
        game_rank = int((game_integrity or {}).get("rank", -1))
    except (TypeError, ValueError):
        return False
    return bool(
        assistant_rank >= 0 and game_rank >= 0
        and assistant_rank >= game_rank
    )


def process_integrity_level(process_id: int | None = None) -> dict:
    """Read one process integrity label without paths, command lines, or handles."""
    pid = int(process_id or os.getpid())
    unknown = {"level": "Unknown", "rank": -1}
    if pid <= 0:
        return {**unknown, "error": "invalid-process-id"}

    process_query_limited_information = 0x1000
    token_query = 0x0008
    token_integrity_level = 25
    kernel32 = ctypes.windll.kernel32
    advapi32 = ctypes.windll.advapi32

    kernel32.OpenProcess.argtypes = (
        wintypes.DWORD, wintypes.BOOL, wintypes.DWORD,
    )
    kernel32.OpenProcess.restype = wintypes.HANDLE
    kernel32.CloseHandle.argtypes = (wintypes.HANDLE,)
    kernel32.CloseHandle.restype = wintypes.BOOL
    advapi32.OpenProcessToken.argtypes = (
        wintypes.HANDLE, wintypes.DWORD, ctypes.POINTER(wintypes.HANDLE),
    )
    advapi32.OpenProcessToken.restype = wintypes.BOOL
    advapi32.GetTokenInformation.argtypes = (
        wintypes.HANDLE, ctypes.c_int, wintypes.LPVOID, wintypes.DWORD,
        ctypes.POINTER(wintypes.DWORD),
    )
    advapi32.GetTokenInformation.restype = wintypes.BOOL
    advapi32.GetSidSubAuthorityCount.argtypes = (wintypes.LPVOID,)
    advapi32.GetSidSubAuthorityCount.restype = ctypes.POINTER(ctypes.c_ubyte)
    advapi32.GetSidSubAuthority.argtypes = (wintypes.LPVOID, wintypes.DWORD)
    advapi32.GetSidSubAuthority.restype = ctypes.POINTER(wintypes.DWORD)

    process_handle = kernel32.OpenProcess(
        process_query_limited_information, False, pid,
    )
    if not process_handle:
        return {**unknown, "error": f"open-process-{kernel32.GetLastError()}"}
    token_handle = wintypes.HANDLE()
    try:
        if not advapi32.OpenProcessToken(
            process_handle, token_query, ctypes.byref(token_handle),
        ):
            return {**unknown, "error": f"open-token-{kernel32.GetLastError()}"}
        required = wintypes.DWORD(0)
        advapi32.GetTokenInformation(
            token_handle, token_integrity_level, None, 0, ctypes.byref(required),
        )
        if required.value <= 0:
            return {**unknown, "error": f"token-size-{kernel32.GetLastError()}"}
        buffer = ctypes.create_string_buffer(required.value)
        if not advapi32.GetTokenInformation(
            token_handle, token_integrity_level, buffer, required.value,
            ctypes.byref(required),
        ):
            return {**unknown, "error": f"token-info-{kernel32.GetLastError()}"}
        sid = ctypes.cast(buffer, ctypes.POINTER(wintypes.LPVOID)).contents.value
        if not sid:
            return {**unknown, "error": "missing-integrity-sid"}
        count_pointer = advapi32.GetSidSubAuthorityCount(sid)
        if not count_pointer or count_pointer[0] <= 0:
            return {**unknown, "error": "missing-integrity-rid"}
        rid_pointer = advapi32.GetSidSubAuthority(sid, count_pointer[0] - 1)
        if not rid_pointer:
            return {**unknown, "error": "missing-integrity-rid"}
        level = integrity_level_from_rid(rid_pointer[0])
        return {"level": level, "rank": INTEGRITY_LEVEL_RANKS[level]}
    except (OSError, TypeError, ValueError) as error:
        return {**unknown, "error": type(error).__name__}
    finally:
        if token_handle:
            kernel32.CloseHandle(token_handle)
        kernel32.CloseHandle(process_handle)


def safe_diagnostic_log_files(live_root: Path, limit: int = DIAGNOSTIC_LOG_LIMIT) -> list[Path]:
    """Return only recent text event/error logs from the dedicated live folder."""
    if limit <= 0 or not live_root.is_dir():
        return []
    candidates: dict[str, Path] = {}
    for pattern in ("events-*.jsonl", "startup-error-*.log"):
        for path in live_root.glob(pattern):
            if path.is_file():
                candidates[path.name.casefold()] = path
    return sorted(
        candidates.values(),
        key=lambda path: (path.stat().st_mtime, path.name),
        reverse=True,
    )[:limit]


def _bounded_log_tail(path: Path, byte_limit: int) -> tuple[bytes, bool]:
    size = path.stat().st_size
    if size <= byte_limit:
        return path.read_bytes(), False
    with path.open("rb") as handle:
        handle.seek(max(0, size - byte_limit))
        handle.readline()  # Drop a partial JSON/text line at the truncation edge.
        payload = handle.read(byte_limit)
        if not payload:
            # One abnormally long line is still more useful than an empty log.
            handle.seek(max(0, size - byte_limit))
            payload = handle.read(byte_limit)
    return payload, True


def _redact_local_paths(payload: bytes) -> bytes:
    """Remove local Windows paths while preserving surrounding diagnostic text."""
    text = payload.decode("utf-8", errors="replace")
    redacted = re.sub(
        r'(?i)(?:[A-Z]:[\\/]|\\\\)[^"\r\n]*',
        "<local-path>",
        text,
    )
    return redacted.encode("utf-8")


def _event_log_session_id(path: Path) -> str | None:
    """Derive a stable, non-identifying session id from the startup event."""
    if not path.name.startswith("events-"):
        return None
    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for _index, line in zip(range(32), handle):
                try:
                    row = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if row.get("event") != "assistant-started":
                    continue
                seed = "|".join(str(row.get(key, "")) for key in (
                    "time", "processId", "buildFingerprint",
                ))
                return hashlib.sha256(seed.encode("utf-8")).hexdigest()[:16]
    except OSError:
        return None
    return None


def diagnostic_package_metadata(app_root: Path) -> dict:
    """Compare runtime identity with the package report copied beside the EXE."""
    common = dict(runtimeVersion=APP_VERSION, runtimeBuildFingerprint=BUILD_FINGERPRINT,
        executionMode='packaged' if getattr(sys, 'frozen', False) else 'source',
        executableVerification='not-performed', consistencyScope='version-and-short-fingerprint-only',
        releaseReportSourceCommit=None, releaseReportBuiltAt=None,
        releaseReportExecutableSha256=None, releaseReportSourceDirty=None)
    report_path = app_root / "release-report.json"
    if not report_path.is_file():
        return {
            **common,
            "status": "release-report-missing",
            "releaseReportPresent": False,
            "runtimeVersion": APP_VERSION,
            "runtimeBuildFingerprint": BUILD_FINGERPRINT,
            "versionConsistent": None,
            "buildFingerprintConsistent": None,
        }
    try:
        report = json.loads(report_path.read_text(encoding="utf-8-sig"))
        if not isinstance(report, dict):
            raise ValueError('release-report-not-object')
    except (OSError, ValueError):
        return {
            **common,
            "status": "release-report-invalid",
            "releaseReportPresent": True,
            "runtimeVersion": APP_VERSION,
            "runtimeBuildFingerprint": BUILD_FINGERPRINT,
            "versionConsistent": None,
            "buildFingerprintConsistent": None,
        }
    report_version = str(report.get("version") or "")
    report_fingerprint = str(
        report.get("buildFingerprint") or ""
    ).upper()
    version_consistent = report_version == APP_VERSION
    fingerprint_consistent = report_fingerprint == BUILD_FINGERPRINT
    for source, target, length in (('sourceCommit', 'releaseReportSourceCommit', 40),
                                  ('executableSha256', 'releaseReportExecutableSha256', 64),
                                  ('sourcePatchSha256', 'releaseReportSourcePatchSha256', 64)):
        value = report.get(source)
        common[target] = value if isinstance(value, str) and re.fullmatch(r'[0-9a-fA-F]{'+str(length)+'}', value) else None
    built_at = report.get('builtAt')
    if isinstance(built_at, str):
        try:
            datetime.fromisoformat(built_at)
            common['releaseReportBuiltAt'] = built_at
        except ValueError:
            pass
    dirty = report.get('sourceDirty')
    common['releaseReportSourceDirty'] = dirty if isinstance(dirty, bool) else None
    dirty_files = report.get('sourceDirtyFiles')
    common['releaseReportSourceDirtyFiles'] = (list(dirty_files) if isinstance(dirty_files, list)
        and all(isinstance(path, str) for path in dirty_files) else None)
    complete = all(common[key] is not None for key in ('releaseReportSourceCommit',
        'releaseReportBuiltAt', 'releaseReportExecutableSha256', 'releaseReportSourceDirty'))
    return {
        **common,
        "status": (
            ("consistent" if complete else "release-report-incomplete")
            if version_consistent and fingerprint_consistent
            else "package-runtime-mismatch"
        ),
        "releaseReportPresent": True,
        "runtimeVersion": APP_VERSION,
        "runtimeBuildFingerprint": BUILD_FINGERPRINT,
        "releaseReportVersion": report_version or None,
        "releaseReportBuildFingerprint": report_fingerprint or None,
        "versionConsistent": version_consistent,
        "buildFingerprintConsistent": fingerprint_consistent,
    }


def diagnostic_version_label(metadata: dict) -> str:
    prefix = f"v{APP_VERSION} · {BUILD_FINGERPRINT}"
    if metadata.get('executionMode') == 'source':
        prefix += ' · 源码模式'
    if metadata.get('status') != 'consistent':
        return prefix + '\n发布报告缺失、不完整或不匹配 · EXE未核验'
    return (prefix + '\n报告声明：' + metadata['releaseReportSourceCommit'][:12]
        + ' · ' + metadata['releaseReportBuiltAt']
        + (' · dirty' if metadata['releaseReportSourceDirty'] else ' · clean')
        + ' · EXE未核验')


def diagnostic_runtime_context(
    display_environment: dict | None,
    *,
    game_window_bound: bool,
    game_foreground: bool,
    map_open: bool,
) -> dict:
    """Keep a small privacy-safe environment snapshot for tester comparisons."""
    safe_display_keys = (
        "clientWidth",
        "clientHeight",
        "clientOrigin",
        "clientBounds",
        "dpi",
        "scalePercent",
        "clientAspect",
        "windowMode",
        "monitorCount",
        "monitorId",
        "monitorBounds",
        "monitorWorkArea",
        "topologySignature",
        "dpiAwareness",
        "verifiedCommonRange",
        "reasons",
        "adaptationPolicy",
        "windowsVersion",
    )
    source = dict(display_environment or {})
    safe_display = {
        key: source[key]
        for key in safe_display_keys
        if key in source
    }
    return {
        "collectionStatus": "captured",
        "displayEnvironment": safe_display,
        "gameWindowBound": bool(game_window_bound),
        "gameForeground": bool(game_foreground),
        "mapOpen": bool(map_open),
    }


def export_safe_diagnostic_bundle(
    app_root: Path,
    live_root: Path,
    *,
    exported_at: datetime | None = None,
    log_limit: int = DIAGNOSTIC_LOG_LIMIT,
    file_byte_limit: int = DIAGNOSTIC_FILE_BYTE_LIMIT,
    total_byte_limit: int = DIAGNOSTIC_TOTAL_BYTE_LIMIT,
    window_environment: dict | None = None,
    runtime_context: dict | None = None,
    package_metadata: dict | None = None,
) -> dict:
    """Create a bounded text-only diagnostic ZIP and exclude all screenshot memory."""
    moment = exported_at or datetime.now().astimezone()
    destination_root = app_root / "outputs" / "诊断日志"
    destination_root.mkdir(parents=True, exist_ok=True)
    base_name = f"第五人格小抄助手-诊断日志-{moment:%Y%m%d-%H%M%S}"
    destination = destination_root / f"{base_name}.zip"
    suffix = 2
    while destination.exists():
        destination = destination_root / f"{base_name}-{suffix}.zip"
        suffix += 1

    logs = safe_diagnostic_log_files(live_root, limit=log_limit)
    included_logs: list[dict] = []
    included_bytes = 0
    fd, temporary_name = tempfile.mkstemp(
        prefix=".diagnostic-export-", suffix=".tmp", dir=destination_root,
    )
    os.close(fd)
    temporary = Path(temporary_name)
    try:
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for path in logs:
                remaining = total_byte_limit - included_bytes
                if remaining <= 0:
                    break
                payload, truncated = _bounded_log_tail(
                    path, max(1, min(file_byte_limit, remaining)),
                )
                payload = _redact_local_paths(payload)
                archive.writestr(f"logs/{path.name}", payload)
                included_bytes += len(payload)
                included_sha256 = hashlib.sha256(payload).hexdigest().upper()
                included_logs.append({
                    "name": path.name,
                    "sourceBytes": path.stat().st_size,
                    "includedBytes": len(payload),
                    "truncatedToRecentLines": truncated,
                    "includedSha256": included_sha256,
                    "sessionId": (
                        _event_log_session_id(path)
                        or (
                            included_sha256[:16].lower()
                            if path.name.startswith("events-") else None
                        )
                    ),
                })

            version_files: list[str] = []
            for name in ("VERSION.txt", "release-report.json", "SHA256SUMS.txt"):
                path = app_root / name
                if path.is_file() and path.stat().st_size <= 1024 * 1024:
                    archive.write(path, f"version/{name}")
                    version_files.append(name)

            package_metadata_source = 'startup-snapshot' if package_metadata is not None else 'export-time-report'
            package_metadata = package_metadata if package_metadata is not None else diagnostic_package_metadata(app_root)
            manifest = {
                "schema": "identityv-safe-diagnostic-export-v2",
                "exportedAt": moment.isoformat(timespec="seconds"),
                "appVersion": APP_VERSION,
                "buildFingerprint": BUILD_FINGERPRINT,
                "runtimeProcessIntegrity": process_integrity_level(),
                "requestedExecutionLevel": "requireAdministrator",
                "textOnly": True,
                "privacy": (
                    "Only recent event/startup text logs, package version files, and privacy-safe "
                    "Identity V window metadata are included. Screenshots, full executable paths, "
                    "nightmare-memory, confirmations, and user settings are excluded."
                ),
                "windowEnvironment": window_environment or {
                    "schema": "identityv-window-environment-v1",
                    "candidateCount": 0,
                    "candidates": [],
                    "collectionStatus": "not-requested",
                },
                "packageMetadata": package_metadata,
                "packageMetadataSource": package_metadata_source,
                "runtimeContext": runtime_context or {
                    "collectionStatus": "not-provided",
                },
                "logs": included_logs,
                "versionFiles": version_files,
            }
            archive.writestr(
                "diagnostic-manifest.json",
                json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"),
            )
        os.replace(temporary, destination)
    finally:
        if temporary.exists():
            temporary.unlink()
    return {
        "path": destination,
        "includedLogCount": len(included_logs),
        "windowCandidateCount": int(
            (window_environment or {}).get("candidateCount", 0),
        ),
        "truncatedLogCount": sum(
            1 for row in included_logs if row["truncatedToRecentLines"]
        ),
        "packageMetadataStatus": package_metadata["status"],
    }


def clamped_float(value, default: float, minimum: float, maximum: float) -> float:
    """Parse persisted UI numbers defensively and keep them in a safe range."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        number = float(default)
    if not np.isfinite(number):
        number = float(default)
    return min(maximum, max(minimum, number))


def tk_widget_exists(widget: object | None) -> bool:
    """Return whether a Tk widget still has a live Tcl command."""
    if widget is None:
        return False
    try:
        return bool(widget.winfo_exists())
    except (AttributeError, tk.TclError):
        return False


def tk_widget_is_viewable(widget: object | None) -> bool:
    """Query viewability without touching a destroyed widget."""
    if not tk_widget_exists(widget):
        return False
    try:
        return bool(widget.winfo_viewable())
    except (AttributeError, tk.TclError):
        return False


def fuse_temporal_candidate_evidence(
    current_rows: list[dict],
    history: list[dict] | None,
    floor: str,
    *,
    now: float | None = None,
    maximum_age_seconds: float = 45.0,
    maximum_frames: int = 6,
) -> tuple[list[dict], list[dict], dict]:
    """Carry reliable side-door evidence across brief map reopen cycles.

    One occluded frame must not erase a direction that was visibly proven a
    few seconds earlier.  We retain only same-floor observations, refuse tied
    direction votes, and require three independent rankings plus a clear
    within-direction winner before temporal evidence may create an automatic
    suggestion.  Automation still only ranks; current-frame alignment remains
    the separate visibility gate.
    """
    timestamp = time.monotonic() if now is None else float(now)
    kept = []
    for snapshot in history or []:
        try:
            age = timestamp - float(snapshot.get("at"))
        except (TypeError, ValueError):
            continue
        if (
            snapshot.get("floor") == floor
            and 0.0 <= age <= float(maximum_age_seconds)
            and isinstance(snapshot.get("rows"), list)
        ):
            kept.append(snapshot)
    raw_rows = [dict(row) for row in current_rows if isinstance(row, dict)]
    kept.append({
        "at": timestamp,
        "floor": floor,
        "rows": [dict(row) for row in raw_rows],
    })
    kept = kept[-max(1, int(maximum_frames)):]

    direction_votes: dict[str, int] = {}
    direction_margins: dict[str, float] = {}
    for snapshot in kept:
        rows = snapshot["rows"]
        top = rows[0] if rows else {}
        direction = top.get("sideDoorDirection")
        if top.get("sideDoorDirectionReliable") and direction:
            key = str(direction)
            direction_votes[key] = direction_votes.get(key, 0) + 1
            direction_margins[key] = max(
                direction_margins.get(key, 0.0),
                float(top.get("sideDoorDirectionMargin", 0.0)),
            )
    retained_direction = None
    if direction_votes:
        ordered_votes = sorted(
            direction_votes.items(), key=lambda pair: pair[1], reverse=True,
        )
        best_direction, best_count = ordered_votes[0]
        second_count = ordered_votes[1][1] if len(ordered_votes) > 1 else 0
        if best_count > second_count:
            retained_direction = best_direction

    fused = [dict(row) for row in raw_rows]
    temporal_auto_lock = False
    consensus_frames = 0
    consensus_wins: dict[str, int] = {}
    consensus_quality: dict[str, list[float]] = {}
    consensus_lead = 0.0
    temporal_identity_verified = False
    if retained_direction:
        current_top = raw_rows[0] if raw_rows else {}
        current_direction_verified = bool(
            current_top.get("sideDoorDirectionReliable")
            and current_top.get("sideDoorDirection") == retained_direction
        )
        for row in fused:
            row["sideDoorDirection"] = retained_direction
            row["sideDoorDirectionReliable"] = True
            row["sideDoorDirectionSupported"] = True
            row["sideDoorDirectionMargin"] = round(
                direction_margins.get(retained_direction, 0.0), 4,
            )
            if not current_direction_verified:
                row["sideDoorDirectionEvidence"] = "temporal-side-door-evidence"
                row["temporalDirectionReused"] = True
                if row.get("direction") == retained_direction:
                    boost = 120.0
                    row["directionHintBoost"] = round(
                        float(row.get("directionHintBoost", 0.0)) + boost, 3,
                    )
                    row["score"] = round(float(row.get("score", 0.0)) + boost, 3)

        for snapshot in kept:
            candidates = [
                row for row in snapshot["rows"]
                if row.get("direction") == retained_direction
            ]
            candidates.sort(
                key=lambda row: float(row.get("score", -999.0)), reverse=True,
            )
            if not candidates:
                continue
            consensus_frames += 1
            consensus_wins[str(candidates[0].get("mapId"))] = (
                consensus_wins.get(str(candidates[0].get("mapId")), 0) + 1
            )
            denominator = max(1, len(candidates) - 1)
            for index, row in enumerate(candidates):
                map_id = str(row.get("mapId"))
                quality = 1.0 - float(index) / denominator
                consensus_quality.setdefault(map_id, []).append(quality)

        average_quality = {
            map_id: sum(values) / len(values)
            for map_id, values in consensus_quality.items() if values
        }
        quality_order = sorted(
            average_quality.items(), key=lambda pair: pair[1], reverse=True,
        )
        if quality_order:
            consensus_lead = quality_order[0][1] - (
                quality_order[1][1] if len(quality_order) > 1 else 0.0
            )
        available_boost = min(36.0, max(0, consensus_frames - 1) * 12.0)
        for row in fused:
            quality = average_quality.get(str(row.get("mapId")), 0.0)
            boost = available_boost * quality
            row["temporalConsensusBoost"] = round(boost, 3)
            row["temporalConsensusFrames"] = consensus_frames
            row["score"] = round(float(row.get("score", 0.0)) + boost, 3)
        fused.sort(key=lambda row: float(row.get("score", -999.0)), reverse=True)

        if fused and quality_order:
            consensus_map = quality_order[0][0]
            required_wins = max(2, (consensus_frames + 1) // 2)
            consensus_semantic_rows = [
                row
                for snapshot in kept
                for row in snapshot["rows"]
                if str(row.get("mapId")) == consensus_map
            ]
            semantic_scores = [
                float(row.get("semanticScore", 0.0))
                for row in consensus_semantic_rows
            ]
            temporal_identity_verified = bool(
                semantic_scores
                and sum(semantic_scores) / len(semantic_scores) >= 0.88
                and any(
                    bool(row.get("identityHardGatePassed"))
                    for row in consensus_semantic_rows
                )
                and max(
                    (int(row.get("semanticMemoryCount", 0))
                     for row in consensus_semantic_rows),
                    default=0,
                ) >= 1
            )
            temporal_auto_lock = bool(
                consensus_frames >= 3
                and str(fused[0].get("mapId")) == consensus_map
                and consensus_wins.get(consensus_map, 0) >= required_wins
                and consensus_lead >= 0.15
                and temporal_identity_verified
            )
            if temporal_auto_lock:
                fused[0]["identityHardGatePassed"] = True
                fused[0]["identityEvidence"] = "accepted-exemplar-temporal-consensus"
                fused[0]["strongSuggestion"] = True
                fused[0]["temporalStrongSuggestion"] = True

    return fused, kept, {
        "historyFrames": len(kept),
        "retainedDirection": retained_direction,
        "directionVotes": direction_votes,
        "consensusFrames": consensus_frames,
        "consensusLead": round(consensus_lead, 4),
        "temporalIdentityVerified": temporal_identity_verified,
        "temporalStrongSuggestion": temporal_auto_lock,
    }


def automatic_direction_hint(auto_scores: dict[str, dict]) -> str | None:
    """Return the best reliable automatic hint without turning it into a filter."""
    reliable = [
        row for row in auto_scores.values()
        if row.get("sideDoorDirectionReliable") and row.get("sideDoorDirection")
    ]
    if not reliable:
        return None
    reliable.sort(key=lambda row: float(row.get("score", -999.0)), reverse=True)
    return str(reliable[0]["sideDoorDirection"])


def automatic_candidate_ranking_is_ready(
    auto_scores: dict[str, dict],
) -> bool:
    """Show the bounded shortlist even when side-door evidence is unavailable."""
    return any(
        isinstance(row, dict)
        for row in auto_scores.values()
    )


def candidate_maps_for_display(
    pack: NightmarePack,
    direction: str,
    door_count: str,
    shape: str,
    auto_scores: dict[str, dict],
) -> list:
    """Apply only explicit human filters; automation may reorder but never hide."""
    maps = pack.filter(direction, door_count, shape)
    maps.sort(
        key=lambda item: float(auto_scores.get(item.id, {}).get("score", -999.0)),
        reverse=True,
    )
    return maps


def candidate_card_text(
    item,
    score: str,
    learned: str = "",
    *,
    prefix: str = "",
    confirmed: bool = False,
) -> str:
    """Present the evidence in the same order a player uses to compare maps."""
    title = f"已锁定 · {item.name}" if confirmed else f"{prefix}{item.name}"
    return (
        f"  {title}\n"
        f"  朝向 {item.direction}  →  房型 {item.shape}  ·  出口 {item.door_count}"
    )


