def _primary_hotkey_to_vk(value: str) -> tuple[str, int]:
    raw = value.strip()
    name = HOTKEY_ALIASES.get(raw, HOTKEY_ALIASES.get(raw.upper(), raw.upper()))
    if name in NAMED_HOTKEYS:
        return name, NAMED_HOTKEYS[name]
    if name in OEM_HOTKEYS:
        return name, OEM_HOTKEYS[name]
    if len(name) == 1 and name in "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789":
        return name, ord(name)
    if name.startswith("F") and name[1:].isdigit() and 1 <= int(name[1:]) <= 24:
        return name, 0x70 + int(name[1:]) - 1
    raise ValueError(
        "没识别到这个键。Fn 和滚轮滚动无法单独录入；"
        "其他键请点“重新录入”后再按一下。"
    )


def hotkey_to_vk(value: str) -> tuple[str, int]:
    chord = parse_chord(value, _primary_hotkey_to_vk)
    return chord.name, chord.vk


def hotkey_capture_candidates() -> tuple[tuple[str, int], ...]:
    """Return one canonical name for every non-Escape key we can observe."""
    candidates = [
        *((f"F{index}", 0x70 + index - 1) for index in range(1, 25)),
        *((letter, ord(letter)) for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
        *((digit, ord(digit)) for digit in "0123456789"),
        *NAMED_HOTKEYS.items(),
        *OEM_HOTKEYS.items(),
    ]
    seen: set[int] = set()
    unique: list[tuple[str, int]] = []
    for name, vk in candidates:
        if int(vk) in {0x10, 0x11, 0x12, 0x5B, 0x5C}:
            continue  # Modifiers are combined with a primary, or recorded on their own release.
        if int(vk) in seen:
            continue
        seen.add(int(vk))
        unique.append((str(name), int(vk)))
    return tuple(unique)


def hotkey_display_name(name: str) -> str:
    return HOTKEY_DISPLAY_NAMES.get(str(name), str(name))


def async_key_edge(raw_state: int, was_down: bool) -> tuple[bool, bool, str | None]:
    """Return a pass-through key edge, including very short presses.

    GetAsyncKeyState's high bit reports the current level. A physical or
    remapped press can begin and end between two polls, so use its low-bit
    pressed-since-last-read latch as a recovery signal. This remains a
    read-only observer and never consumes or injects the game's input.
    """
    state = int(raw_state) & 0xFFFF
    down = bool(state & 0x8000)
    if down and not was_down:
        return True, down, "level-edge"
    if bool(state & 0x0001) and not was_down:
        return True, down, "latched-short-press"
    return False, down, None


def hotkey_capture_edge(
    raw_state: int,
    was_down: bool,
    *,
    activation_key_suppressed: bool = False,
) -> tuple[bool, bool, str | None]:
    """Observe a capture edge without a grace-period that swallows quick keys."""
    state = int(raw_state) & 0xFFFF
    down = bool(state & 0x8000)
    if activation_key_suppressed:
        return False, down, "activation-key-suppressed"
    return async_key_edge(state, was_down)


def parse_action_hotkeys(value: str, map_hotkey_vk: int | None = None,
                         map_hotkey_name: str | None = None) -> dict[str, tuple[str, int]]:
    names = ([part.strip() for part in re.split(r"[,，/]", value)]
             if re.search(r"[,，/]", value) else value.split())
    if len(names) not in {6, 7, 8, len(ACTION_ORDER)}:
        raise ValueError("功能键项目不完整；未绑定项可以留空")
    parsed = [hotkey_to_vk(name) for name in names]
    if len(parsed) == 6:
        # beta.2.10 and older stored six actions. Preserve every customized
        # key, then assign the first free F-key to the new visibility action.
        used = {vk for _name, vk in parsed}
        for candidate in (
            ACTION_HOTKEYS["toggle-sheet-visibility"][0],
            *(f"F{index}" for index in range(12, 25)),
        ):
            canonical = hotkey_to_vk(candidate)
            if canonical[1] not in used and canonical[1] != map_hotkey_vk:
                parsed.append(canonical)
                break
        if len(parsed) != 7:
            raise ValueError("无可用按键用于小抄显影；请手动填写第 7 个功能键")
    if len(parsed) == 7:
        parsed.append(("", 0))  # New start has no chosen default; explicit empty stays unbound.
    if len(parsed) == 8:
        parsed.append(("", 0))  # Existing end stays one-way; toggle has no migrated default.
    compiled = {target: parse_chord(pair[0], _primary_hotkey_to_vk)
                for target, pair in zip(ACTION_ORDER, parsed)}
    if map_hotkey_name is not None:
        compiled["map"] = parse_chord(map_hotkey_name, _primary_hotkey_to_vk)
    elif map_hotkey_vk and any(vk == map_hotkey_vk for _name, vk in parsed):
        raise ValueError("功能键不能与地图键重复")
    validate_unique(compiled)
    return dict(zip(ACTION_ORDER, parsed))


def recover_action_hotkeys(configured, defaults: dict, map_name: str) -> dict[str, tuple[str, int]]:
    """Keep readable legacy choices; unbind invalid/conflicting items, never reassign."""
    if configured is None:
        names = [defaults[action][0] for action in ACTION_ORDER]
    elif isinstance(configured, list) and len(configured) in {6, 7, 8, len(ACTION_ORDER)}:
        names = [*configured, *([""] * (len(ACTION_ORDER) - len(configured)))]
    else:
        names = [""] * len(ACTION_ORDER)
    accepted = {"map": parse_chord(map_name, _primary_hotkey_to_vk)}
    recovered = {}
    for action, name in zip(ACTION_ORDER, names):
        try:
            if not isinstance(name, str):
                raise ValueError("invalid key type")
            chord = parse_chord(name, _primary_hotkey_to_vk)
            validate_unique({**accepted, action: chord})
        except ValueError:
            chord = Chord("", 0)
        accepted[action] = chord
        recovered[action] = (chord.name, chord.vk)
    return recovered


SHEET_VISIBLE_STATUS_FRAGMENTS = (
    "小抄已显示", "小抄已贴合", "小抄已更新",
    "小抄保持悬浮", "保留小抄", "保留悬浮小抄",
    "悬浮小抄保持显示", "已悬浮小抄", "小抄保持显示",
    "小抄正在跟随", "小抄仍可继续使用", "切换悬浮小抄",
    "按审核过的一二楼房间映射显示",
)


def sheet_visibility_status_text(text: str, enabled: bool) -> str:
    """Never claim a route is visible while the player has hidden it."""
    value = str(text or "")
    if enabled or not any(fragment in value for fragment in SHEET_VISIBLE_STATUS_FRAGMENTS):
        return value
    for fragment in SHEET_VISIBLE_STATUS_FRAGMENTS:
        value = value.replace(fragment, "定点地图按设置隐藏")
    return value


def probable_map_interface(evidence: dict) -> bool:
    """Accept the nightmare canvas even when legacy UI-anchor checks differ."""
    if evidence.get('tintedControlsLocalized') is False:
        return False
    backdrop = float(evidence.get("backdropRatio", 0.0))
    anchors = int(evidence.get("matchedAnchors", 0))
    if evidence.get("layoutFamily") == "narrow-4x3":
        # The newly-supported layout must retain strong map-only proof.  Do not
        # let the broad legacy fallback authorize a dark 4:3 gameplay frame.
        return bool(evidence.get("detected"))
    return bool(
        evidence.get("detected")
        or (evidence.get("flatMapCanvas") and anchors >= 1 and backdrop >= 0.80)
        or (anchors >= 3 and backdrop >= 0.75)
    )


def capture_visual_attempt_can_finish(
    *,
    silent_hint: bool,
    probable: bool,
    strict_hotkey_map: bool,
    locked_canvas_without_floor: bool,
    require_locked_round_floor_evidence: bool,
) -> bool:
    """Finish immediately only when this frame has the required evidence.

    Daily behavior can still accept a locked map canvas before its floor
    selector settles. Development tests may keep using the existing bounded
    capture window until the selector becomes explicit; loop exhaustion is
    handled by the caller and remains fail-closed for overlay reuse.
    """
    if not silent_hint:
        return bool(probable)
    if strict_hotkey_map:
        return True
    return bool(
        locked_canvas_without_floor
        and not require_locked_round_floor_evidence
    )


def locked_round_floor_evidence_required(
    enabled: bool,
    locked_floor: str | None,
) -> bool:
    """Use the accepted floor-highlight wait only for a locked front entry."""
    return bool(enabled and str(locked_floor) == "1")


def locked_round_wide_translation_radius(
    frame_shape,
    local_radius: float,
    *,
    first_floor_verification: bool,
) -> float:
    """Cover a real floor recenter while keeping scale and rotation fixed."""
    try:
        height, width = int(frame_shape[0]), int(frame_shape[1])
    except (TypeError, ValueError, IndexError):
        height, width = 0, 0
    viewport_radius = max(height, width) * (
        0.5 if first_floor_verification else 0.32
    )
    minimum = 480.0 if first_floor_verification else 300.0
    return float(min(
        LOCKED_ROUND_WIDE_TRANSLATION_MAXIMUM_PIXELS,
        max(minimum, float(local_radius) * 2.0, viewport_radius),
    ))


def shared_group_wide_recovery_required(
    floor: str,
    *,
    has_target_floor_evidence: bool,
    phase_reason: str | None,
    transition_or_jump: bool = False,
) -> bool:
    """Reserve broad B1 translation for an explicit transition/jump or a
    state-machine escalation after continuous local failure.

    A stable B1 reopen follows the same local-first path as F1/F2. Missing
    pixels or a local phase failure alone do not authorize a broad search.
    """
    _ = bool(has_target_floor_evidence), str(phase_reason or "")
    return bool(str(floor) == "B1" and transition_or_jump)


def locked_map_selected_relocalization_is_allowed(floor: str) -> bool:
    """Allow a confirmed-map fit without reopening map identity search.

    This is the bounded beta.2.4 continuation step after shared-pose edge
    correction misses.  It is valid on every round layer, but it never grants
    display authority by itself: the target open-map frame must still pass the
    selected-route residual gate before the shared pose can be promoted.
    """
    return str(floor) in ROUND_LAYER_FLOORS


def locked_map_relocalization_may_follow_edge_fallback(
    floor: str,
    *,
    current_floor_relocalization: bool,
) -> bool:
    """Preserve local-first recovery and the stricter B1 wide-search gate."""
    normalized_floor = str(floor)
    if normalized_floor in {"1", "2"}:
        return True
    return bool(
        normalized_floor == "B1"
        and not current_floor_relocalization
    )


def same_map_pose_initialization_is_allowed(
    map_id: str,
    floor: str,
    confirmed_map_id: str | None,
    *,
    pose_pending: bool,
    shared_group_pose_seeded: bool,
    local_seed_available: bool,
    already_attempted: bool,
) -> bool:
    """Authorize one confirmed-map F1/F2 pose search before a group exists.

    A local candidate is a better starting point, not an already initialized
    pose. It therefore keeps the selected-map initialization state active while
    ensuring the bounded seed refinement runs before any expanded search.
    """
    _ = bool(local_seed_available)
    return bool(
        str(floor) in {"1", "2"}
        and str(map_id) == str(confirmed_map_id or "")
        and pose_pending
        and not shared_group_pose_seeded
        and not already_attempted
    )


def same_map_pose_initialization_attempt_key(
    map_id: str,
    floor: str,
    confirmed_at: str | None,
    cycle_id: int | None,
) -> tuple[str, str, str, int | None]:
    """Scope the one-shot fit guard to one real open-map cycle.

    Identity evidence may come from the front door, a side/exit view, or a
    manual selection. None of those sources owns a separate pose state
    machine. A failed or closed frame therefore cannot consume every future
    attempt for the round.
    """
    return (
        str(map_id),
        str(floor),
        str(confirmed_at or "active"),
        int(cycle_id) if cycle_id is not None else None,
    )


def automatic_candidate_shell_may_open(active_confirmation: dict | None) -> bool:
    """Only first-use uncertainty may open the candidate shell automatically."""
    return not bool(
        isinstance(active_confirmation, dict)
        and active_confirmation.get("mapId")
    )


def alignment_display_hard_limit_ms(
    *, shared_pose_relocalization: bool, target_floor_trusted: bool = True,
) -> float | None:
    """Time-box daily correction, never the round's first trusted pose."""
    return (
        CURRENT_FLOOR_RELOCALIZATION_HARD_LIMIT_MS
        if shared_pose_relocalization and target_floor_trusted else None
    )


def round_group_target_floor_is_trusted(
    group: RoundLayerGroup | None,
    floor: str,
) -> bool:
    """Require both canonical proof and a verified floor-local tracker.

    A shared group can exist because another floor was verified. That root is a
    search seed for an unseen floor, but it does not turn the unseen floor into
    a daily relocalization target or give it the one-second display deadline.
    """
    if group is None or str(floor) not in group.canonical_geometry_verified_floors:
        return False
    tracking = group.tracking_for_floor(str(floor))
    return bool(
        isinstance(tracking, dict)
        and any(
            tracking.get(field) is True
            for field in (
                "poseVerifiedAgainstCanonicalGeometry",
                "poseVerifiedAgainstRenderedProfile",
                "poseVerifiedAgainstLiveGeometry",
            )
        )
    )


def round_group_wide_search_is_allowed(
    floor: str,
    wide_recovery_evidence: str | None,
) -> bool:
    """Wide recovery is B1-only and requires explicit recovery evidence."""
    return bool(
        str(floor) == "B1"
        and str(wide_recovery_evidence or "") in {
            "floor-transition", "position-jump", "display-reprojection",
            "explicit-drag", "continuous-local-failure",
        }
    )


def round_group_recovery_mode(
    group: RoundLayerGroup | None,
    floor: str,
    wide_recovery_evidence: str | None = None,
) -> str:
    """Name the one shared-pose recovery state for telemetry and policy.

    B1 receives one controlled broad translation search only before that floor
    has a current-frame-verified anchor and only for an explicit transition or
    jump. Once B1 is trusted, every reopen/motion correction is local. A
    return from B1 to an upstairs floor remains a shared-root correction; it
    never creates an independently movable floor pose.
    """
    normalized_floor = str(floor)
    if normalized_floor == "B1":
        if str(wide_recovery_evidence or "") == "continuous-local-failure":
            return "continuous-local-failure-wide"
        if round_group_target_floor_is_trusted(group, normalized_floor):
            return "stable-local"
        if round_group_wide_search_is_allowed(
            normalized_floor, wide_recovery_evidence,
        ):
            return "first-teleport-wide"
        return "first-local-awaiting-evidence"
    previous_floor = str(
        getattr(group, "displayed_floor", "")
        or getattr(group, "tracking_floor", "")
    )
    if normalized_floor in {"1", "2"} and previous_floor == "B1":
        return "cross-floor-return"
    return "stable-local"


def _map_frame_signature_token(signature) -> str | None:
    try:
        value = np.asarray(signature, dtype=np.float32)
    except (TypeError, ValueError):
        return None
    if value.size <= 0 or not np.isfinite(value).all():
        return None
    return hashlib.sha256(value.tobytes()).hexdigest()[:20]


FRONT_ANCHOR_DIRECT_MINIMUM_SCALE = 0.03
FRONT_ANCHOR_DIRECT_MAXIMUM_SCALE = 6.0
FRONT_ANCHOR_DIRECT_MAXIMUM_ASPECT_LOG_ERROR = 0.12
FRONT_ANCHOR_DIRECT_MAXIMUM_REPROJECTION_ERROR_PX = 1.0
FRONT_ANCHOR_DIRECT_MINIMUM_SCREEN_OVERLAP = 0.05
FRONT_ANCHOR_DIRECT_MINIMUM_CLIENT_FOOTPRINT = 0.02
FRONT_LOCK_RELIABLE_REASONS = frozenset({
    "front-live-auto-lock-ready",
    "front-live-temporal-lock-ready",
    "front-live-accumulated-unique-structure-lock-ready",
    "front-live-singleton-near-door-lock-ready",
})


def front_lock_reason_is_reliable(reason: str | None) -> bool:
    """Accept only explicit front-door identity lock sources."""
    return str(reason or "") in FRONT_LOCK_RELIABLE_REASONS


def _front_anchor_direct_similarity(
    source_anchor: dict | None,
    live_anchor: dict | None,
    *,
    reference_scale: float = 1.0,
    reference_dx: float = 0.0,
    reference_dy: float = 0.0,
) -> tuple[np.ndarray | None, dict]:
    """Build the one-anchor pose using the recognizer's reviewed scale seed."""
    try:
        source_center = np.asarray(source_anchor["center"], dtype=np.float64)
        live_center = np.asarray(live_anchor["center"], dtype=np.float64)
        source_size = np.asarray(source_anchor["size"], dtype=np.float64)
        live_size = np.asarray(live_anchor["size"], dtype=np.float64)
    except (KeyError, TypeError, ValueError):
        return None, {"reason": "front-anchor-fields-missing"}
    if (
        source_center.shape != (2,)
        or live_center.shape != (2,)
        or source_size.shape != (2,)
        or live_size.shape != (2,)
        or not np.isfinite(source_center).all()
        or not np.isfinite(live_center).all()
        or not np.isfinite(source_size).all()
        or not np.isfinite(live_size).all()
        or np.any(source_size <= 0.0)
        or np.any(live_size <= 0.0)
    ):
        return None, {"reason": "front-anchor-nonpositive-or-nonfinite"}
    try:
        reference_scale = float(reference_scale)
        reference_dx = float(reference_dx)
        reference_dy = float(reference_dy)
    except (TypeError, ValueError):
        return None, {"reason": "front-anchor-reference-geometry-missing"}
    if (
        not np.isfinite([reference_scale, reference_dx, reference_dy]).all()
        or reference_scale <= 0.0
    ):
        return None, {"reason": "front-anchor-reference-geometry-invalid"}
    source_aspect = float(source_size[0] / source_size[1])
    live_aspect = float(live_size[0] / live_size[1])
    aspect_log_error = abs(float(np.log(live_aspect / source_aspect)))
    if aspect_log_error > FRONT_ANCHOR_DIRECT_MAXIMUM_ASPECT_LOG_ERROR:
        return None, {
            "reason": "front-anchor-aspect-mismatch",
            "sourceAspect": source_aspect,
            "liveAspect": live_aspect,
            "aspectLogError": aspect_log_error,
        }
    anchor_scale = float(np.mean(live_size) / np.mean(source_size))
    scale = float(reference_scale * anchor_scale)
    if not FRONT_ANCHOR_DIRECT_MINIMUM_SCALE <= scale <= FRONT_ANCHOR_DIRECT_MAXIMUM_SCALE:
        return None, {
            "reason": "front-anchor-scale-out-of-range",
            "scale": scale,
        }
    target_anchor = np.asarray([
        live_center[0] + live_size.mean() * reference_dx / 10.0,
        live_center[1] + live_size.mean() * (
            9.0 * (1.0 - reference_scale) + reference_dy
        ) / 10.0,
    ])
    translation = target_anchor - source_center * scale
    matrix = np.asarray([
        [scale, 0.0, float(translation[0])],
        [0.0, scale, float(translation[1])],
        [0.0, 0.0, 1.0],
    ], dtype=np.float64)
    reprojected = matrix @ np.asarray([
        source_center[0], source_center[1], 1.0,
    ], dtype=np.float64)
    reprojection_error = float(np.linalg.norm(reprojected[:2] - target_anchor))
    if reprojection_error > FRONT_ANCHOR_DIRECT_MAXIMUM_REPROJECTION_ERROR_PX:
        return None, {
            "reason": "front-anchor-reprojection-mismatch",
            "reprojectionErrorPx": reprojection_error,
        }
    return matrix, {
        "reason": "front-anchor-direct-similarity-ready",
        "scale": scale,
        "anchorScale": anchor_scale,
        "referenceScale": reference_scale,
        "referenceDx": reference_dx,
        "referenceDy": reference_dy,
        "scaleSource": "front-pose-seed-reference-scale",
        "reprojectionErrorPx": reprojection_error,
        "sourceCenter": source_center.tolist(),
        "liveCenter": live_center.tolist(),
    }


def _front_anchor_direct_bounds_sanity(
    matrix_source_to_client,
    route_shape,
    client_shape,
) -> dict:
    """Cheap finite/orientation/bounds gate; no structure search is invoked."""
    try:
        matrix = np.asarray(matrix_source_to_client, dtype=np.float64)
        route_height, route_width = int(route_shape[0]), int(route_shape[1])
        client_height, client_width = int(client_shape[0]), int(client_shape[1])
    except (IndexError, TypeError, ValueError):
        return {"success": False, "reason": "front-anchor-route-bounds-missing"}
    if (
        matrix.shape != (3, 3)
        or not np.isfinite(matrix).all()
        or route_height <= 0
        or route_width <= 0
        or client_height <= 0
        or client_width <= 0
    ):
        return {"success": False, "reason": "front-anchor-route-bounds-invalid"}
    linear = matrix[:2, :2]
    determinant = float(np.linalg.det(linear))
    singular = np.linalg.svd(linear, compute_uv=False)
    scale = float(np.sqrt(abs(determinant)))
    anisotropy = float(singular.max() / max(singular.min(), 1e-9))
    rotation_degrees = float(np.degrees(np.arctan2(linear[1, 0], linear[0, 0])))
    if (
        determinant <= 0.0
        or not FRONT_ANCHOR_DIRECT_MINIMUM_SCALE <= scale <= FRONT_ANCHOR_DIRECT_MAXIMUM_SCALE
        or anisotropy > 1.01
        or abs(rotation_degrees) > 0.5
    ):
        return {
            "success": False,
            "reason": "front-anchor-route-orientation-invalid",
            "scale": scale,
            "anisotropy": anisotropy,
            "rotationDegrees": rotation_degrees,
        }
    corners = np.asarray([
        [0.0, 0.0, 1.0],
        [float(route_width), 0.0, 1.0],
        [float(route_width), float(route_height), 1.0],
        [0.0, float(route_height), 1.0],
    ], dtype=np.float64).T
    projected_h = matrix @ corners
    if np.any(np.abs(projected_h[2]) <= 1e-9):
        return {"success": False, "reason": "front-anchor-route-projection-invalid"}
    projected = (projected_h[:2] / projected_h[2]).T
    if not np.isfinite(projected).all():
        return {"success": False, "reason": "front-anchor-route-projection-invalid"}
    x0, y0 = projected.min(axis=0)
    x1, y1 = projected.max(axis=0)
    intersection = (
        max(0.0, min(float(x1), client_width) - max(float(x0), 0.0))
        * max(0.0, min(float(y1), client_height) - max(float(y0), 0.0))
    )
    box_area = max(1.0, float(x1 - x0) * float(y1 - y0))
    client_area = max(1.0, float(client_width * client_height))
    screen_overlap = float(intersection / min(box_area, client_area))
    client_footprint = float(intersection / client_area)
    if (
        screen_overlap < FRONT_ANCHOR_DIRECT_MINIMUM_SCREEN_OVERLAP
        or client_footprint < FRONT_ANCHOR_DIRECT_MINIMUM_CLIENT_FOOTPRINT
    ):
        return {
            "success": False,
            "reason": "front-anchor-route-outside-client",
            "screenOverlap": screen_overlap,
            "clientFootprint": client_footprint,
            "projectedBounds": [float(x0), float(y0), float(x1), float(y1)],
        }
    return {
        "success": True,
        "reason": "front-anchor-route-bounds-ready",
        "scale": scale,
        "anisotropy": anisotropy,
        "rotationDegrees": rotation_degrees,
        "screenOverlap": screen_overlap,
        "clientFootprint": client_footprint,
        "projectedBounds": [float(x0), float(y0), float(x1), float(y1)],
    }


def _front_scale_matrix_about_client_anchor(
    matrix_source_to_client,
    live_anchor,
    factor: float,
) -> np.ndarray | None:
    """Change only uniform scale while keeping the live door point fixed."""
    matrix = np.asarray(matrix_source_to_client, dtype=np.float64)
    anchor = np.asarray(live_anchor, dtype=np.float64)
    try:
        factor = float(factor)
    except (TypeError, ValueError):
        return None
    if (
        matrix.shape != (3, 3)
        or anchor.shape != (2,)
        or not np.isfinite(matrix).all()
        or not np.isfinite(anchor).all()
        or not np.isfinite(factor)
        or factor <= 0.0
    ):
        return None
    result = matrix.copy()
    result[:2, :2] *= factor
    result[:2, 2] = anchor + factor * (matrix[:2, 2] - anchor)
    return result


def front_terrain_scale_decision(
    engine,
    frame: np.ndarray | None,
    route: np.ndarray | None,
    baseline_matrix,
    live_anchor,
    *,
    route_profile_id: str | None = None,
    independent_residual_fn=None,
    visible_override: tuple | None = None,
    reference_override: np.ndarray | None = None,
) -> dict | None:
    """Run one local H0/H1 geometry estimate on the current visible component.

    ``independent_residual_fn`` remains in the signature for callers from the
    previous contract, but the decision no longer treats a second label or a
    second full-ROI residual as independent evidence. The estimator owns a
    disjoint held-out structure-point set for validation.
    """
    del engine, live_anchor, independent_residual_fn
    result = estimate_front_local_geometry(
        frame,
        route,
        baseline_matrix,
        maximum_dimension=720,
        visible_override=visible_override,
        reference_override=reference_override,
        route_profile_id=route_profile_id,
    )
    return result


def bind_front_pose_seed(
    diagnostics: dict | None,
    map_id: str,
    floor: str,
    *,
    lock_generation: int | None,
    source_frame_signature,
    source_display_signature: tuple | list | None,
    manual_confirmation: bool = False,
    require_source_frame_current: bool = False,
) -> dict | None:
    """Snapshot a current front anchor without granting display yet.

    Manual confirmation may bypass the automatic identity-lock reason, but it
    never bypasses current-frame identity, entrance-anchor, display, or route
    residual gates.
    """
    evidence = diagnostics if isinstance(diagnostics, dict) else {}
    pose_seed = evidence.get("poseSeed") or {}
    entrance = evidence.get("entranceSceneEvidence") or {}
    anchor = evidence.get("anchor") or {}
    layout = str(evidence.get("layoutCandidate") or "unknown")
    detected_layout = str(evidence.get("detectedLayout") or layout)
    signature_token = _map_frame_signature_token(source_frame_signature)
    group_locked = evidence.get("frontGroupLocked") is True
    group_layout = str(evidence.get("frontGroupLayout") or "unknown")
    layout_gate_passed = bool(
        layout != "unknown" and detected_layout == layout
    ) or bool(group_locked and group_layout != "unknown")
    if manual_confirmation and layout != "unknown":
        layout_gate_passed = True
    if not (
        str(floor) == "1"
        and str(map_id or "")
        and (
            manual_confirmation
            or (
                front_lock_reason_is_reliable(evidence.get("reason"))
                and evidence.get("automaticMapLockAllowed") is True
            )
        )
        and str(evidence.get("candidateMapId") or "") == str(map_id)
        and str(pose_seed.get("mapId") or "") == str(map_id)
        and anchor.get("supported") is True
        and entrance.get("verified") is True
        and entrance.get("entranceType") == "front-door"
        and layout_gate_passed
        and pose_seed.get("candidateOnly") is True
        and pose_seed.get("currentFrameRouteResidualRequired") is True
        and pose_seed.get("authorizesDirectDisplay") is False
        and (not require_source_frame_current
             or evidence.get("sourceFrameSignatureToken") == signature_token)
    ):
        return None
    matrix, geometry = _front_anchor_direct_similarity(
        pose_seed.get("sourceAnchor"), pose_seed.get("liveAnchor"),
        reference_scale=pose_seed.get("referenceScale", 1.0),
        reference_dx=pose_seed.get("referenceDx", 0.0),
        reference_dy=pose_seed.get("referenceDy", 0.0),
    )
    if matrix is None or signature_token is None:
        return None
    return {
        "mapId": str(map_id),
        "floor": str(floor),
        "matrixSourceToClient": matrix.tolist(),
        "confidence": 1.0,
        "transferSource": "front-door-locked-pose-seed",
        "frontDoorPoseSeed": True,
        "manualConfirmation": bool(manual_confirmation),
        "frontAnchorDirectEligible": True,
        "frontLockReason": str(evidence.get("reason")),
        "frontAnchorSupported": True,
        "entranceSceneVerified": True,
        "layoutGatePassed": True,
        "directSimilarity": geometry,
        "referenceScale": float(geometry["referenceScale"]),
        "referenceDx": float(geometry["referenceDx"]),
        "referenceDy": float(geometry["referenceDy"]),
        "scaleSource": str(geometry["scaleSource"]),
        "candidateOnly": True,
        "currentFrameRouteResidualRequired": True,
        "authorizesDirectDisplay": False,
        "lockGeneration": (
            int(lock_generation) if lock_generation is not None else None
        ),
        "sourceFrameSignatureToken": signature_token,
        "sourceDisplaySignature": list(source_display_signature or ()),
        "sourceAnchor": pose_seed.get("sourceAnchor"),
        "liveAnchor": pose_seed.get("liveAnchor"),
    }


def bind_manual_front_pose_seed_from_current_frame(
    engine,
    map_id: str,
    floor: str,
    frame: np.ndarray | None,
    *,
    lock_generation: int | None,
    source_display_signature: tuple | list | None,
) -> dict | None:
    """Re-read only the current front icon for a manually selected map.

    Manual identity is authoritative here. The fresh scene check supplies
    only the live door anchor; it does not rerun 13-map ranking and cannot
    authorize route pixels without the direct pose contract's later gates.
    """
    if not (
        isinstance(engine, FrontDoorLiveTestEngine)
        and str(floor) == "1"
        and str(map_id or "")
        and isinstance(frame, np.ndarray)
    ):
        return None
    scene = front_entry_scene_evidence(frame, engine)
    if not scene.get("verified"):
        return None
    source_identity = engine.recognizer.identity_rows.get(str(map_id)) or {}
    source_anchor = source_identity.get("frontDoorAnchor") or {}
    layout = str(
        engine.layout_recognizer.map_layouts.get(str(map_id)) or "unknown"
    )
    pose_seed = {
        "mapId": str(map_id),
        "sourceAnchor": {
            "center": list(source_anchor.get("center") or []),
            "size": list(source_anchor.get("size") or []),
        },
        "liveAnchor": {
            "center": list(scene.get("anchorCenter") or []),
            "size": list(scene.get("anchorSize") or []),
        },
        "candidateOnly": True,
        "currentFrameRouteResidualRequired": True,
        "authorizesDirectDisplay": False,
    }
    diagnostics = {
        "reason": "front-live-manual-current-frame-anchor",
        "candidateMapId": str(map_id),
        "automaticMapLockAllowed": False,
        "layoutCandidate": layout,
        "detectedLayout": layout,
        "anchor": {
            "center": list(scene.get("anchorCenter") or []),
            "size": list(scene.get("anchorSize") or []),
            "supported": True,
        },
        "entranceSceneEvidence": scene,
        "poseSeed": pose_seed,
    }
    return bind_front_pose_seed(
        diagnostics,
        str(map_id),
        floor,
        lock_generation=lock_generation,
        source_frame_signature=map_frame_signature(frame),
        source_display_signature=source_display_signature,
        manual_confirmation=True,
    )


def bound_front_pose_seed_is_current(
    seed: dict | None,
    map_id: str,
    floor: str,
    *,
    lock_generation: int | None,
    source_frame_signature,
    source_display_signature: tuple | list | None,
) -> bool:
    """Reject a seed copied from another lock, frame, floor, or display."""
    if not isinstance(seed, dict):
        return False
    try:
        matrix = np.asarray(seed.get("matrixSourceToClient"), dtype=np.float64)
    except (TypeError, ValueError):
        return False
    expected_generation = (
        int(lock_generation) if lock_generation is not None else None
    )
    return bool(
        matrix.shape == (3, 3)
        and np.isfinite(matrix).all()
        and seed.get("candidateOnly") is True
        and seed.get("currentFrameRouteResidualRequired") is True
        and seed.get("authorizesDirectDisplay") is False
        and str(seed.get("mapId") or "") == str(map_id)
        and str(seed.get("floor") or "") == str(floor)
        and seed.get("lockGeneration") == expected_generation
        and seed.get("sourceFrameSignatureToken")
        == _map_frame_signature_token(source_frame_signature)
        and tuple(seed.get("sourceDisplaySignature") or ())
        == tuple(source_display_signature or ())
    )


def front_anchor_direct_pose_contract(
    seed: dict | None,
    map_id: str,
    floor: str,
    *,
    lock_generation: int | None,
    source_frame_signature,
    source_display_signature: tuple | list | None,
    route_shape,
    client_shape,
    map_is_open: bool,
    confirmed_map_id: str | None,
    current_floor: str | None,
    route_adapter_available: bool,
) -> dict:
    """Authorize direct front-anchor display without calling a generic aligner."""
    if not map_is_open:
        return {"success": False, "reason": "front-anchor-map-closed"}
    if str(confirmed_map_id or "") != str(map_id):
        return {"success": False, "reason": "front-anchor-confirmed-map-mismatch"}
    if str(current_floor or "") != str(floor):
        return {"success": False, "reason": "front-anchor-current-floor-mismatch"}
    if not route_adapter_available:
        return {"success": False, "reason": "front-anchor-route-adapter-missing"}
    if not bound_front_pose_seed_is_current(
        seed, map_id, floor,
        lock_generation=lock_generation,
        source_frame_signature=source_frame_signature,
        source_display_signature=source_display_signature,
    ):
        return {"success": False, "reason": "front-anchor-lock-or-frame-stale"}
    if not (
        seed.get("frontAnchorDirectEligible") is True
        and (
            front_lock_reason_is_reliable(seed.get("frontLockReason"))
            or seed.get("manualConfirmation") is True
        )
        and seed.get("frontAnchorSupported") is True
        and seed.get("entranceSceneVerified") is True
        and seed.get("layoutGatePassed") is True
    ):
        return {"success": False, "reason": "front-anchor-reliability-gate-failed"}
    matrix, anchor_meta = _front_anchor_direct_similarity(
        seed.get("sourceAnchor"), seed.get("liveAnchor"),
        reference_scale=seed.get("referenceScale", 1.0),
        reference_dx=seed.get("referenceDx", 0.0),
        reference_dy=seed.get("referenceDy", 0.0),
    )
    if matrix is None:
        return {"success": False, **anchor_meta}
    bounds_meta = _front_anchor_direct_bounds_sanity(
        matrix, route_shape, client_shape,
    )
    if not bounds_meta.get("success"):
        return bounds_meta
    return {
        "success": True,
        "reason": "front-anchor-direct-pose-authorized",
        "matrixSourceToClient": matrix.tolist(),
        "frontAnchorDirectPose": True,
        "genericSearchInvoked": False,
        "directDisplayAuthorized": True,
        "anchorGeometry": anchor_meta,
        "routeBounds": bounds_meta,
    }
PROGRESSIVE_POSE_CANDIDATE_REASONS = {
    "partial-structure-ambiguous",
    "wide-translation-position-not-unique",
}


def progressive_pose_candidate(
    map_id: str,
    floor: str,
    matrix,
    *,
    reason: str,
    coordinate_space: str,
    source_cycle_id: int | None,
    source_frame_signature,
    source_display_signature: tuple | list | None,
    group_generation: int,
    score: float | None = None,
    residual: dict | None = None,
    hypotheses: list | None = None,
) -> dict | None:
    """Build a cross-open search seed; never a display-authorized pose."""
    if str(reason) not in PROGRESSIVE_POSE_CANDIDATE_REASONS:
        return None
    try:
        candidate_matrix = np.asarray(matrix, dtype=np.float64)
    except (TypeError, ValueError):
        return None
    frame_token = _map_frame_signature_token(source_frame_signature)
    if (
        candidate_matrix.shape != (3, 3)
        or not np.isfinite(candidate_matrix).all()
        or frame_token is None
        or coordinate_space not in {"recognition", "render"}
    ):
        return None
    return {
        "mapId": str(map_id),
        "floor": str(floor),
        "matrixSourceToClient": candidate_matrix.tolist(),
        "reason": str(reason),
        "coordinateSpace": coordinate_space,
        "sourceCycleId": source_cycle_id,
        "sourceFrameSignature": np.asarray(
            source_frame_signature, dtype=np.float32,
        ).copy(),
        "sourceFrameSignatureToken": frame_token,
        "sourceDisplaySignature": list(source_display_signature or ()),
        "roundGroupGenerationAtStart": int(group_generation),
        "score": float(score) if score is not None else None,
        "residual": dict(residual) if isinstance(residual, dict) else None,
        "hypotheses": list(hypotheses or [])[:12],
        "independentOpenCount": 1,
        "candidateOnly": True,
        "currentFrameRouteResidualRequired": True,
        "authorizesDirectDisplay": False,
    }


def large_shared_root_translation_requires_continuity(
    floor: str,
    search_tier: str | None,
    translation,
) -> bool:
    """Identify a B1 wide result that needs a second captured frame."""
    delta = np.asarray(translation, dtype=np.float64)
    return bool(
        str(floor) == "B1"
        and str(search_tier or "") in {
            "canonical-geometry-wide",
            "target-floor-relation-wide",
        }
        and delta.shape == (2,)
        and np.isfinite(delta).all()
        and float(np.linalg.norm(delta))
        > float(LARGE_SHARED_ROOT_TRANSLATION_PIXELS)
    )


def _wide_translation_residual_is_distributed(residual: dict | None) -> bool:
    """Apply the existing distributed-geometry gate to one branch residual."""
    row = residual if isinstance(residual, dict) else {}
    try:
        return bool(
            int(row.get("queryEdgeGridCells3x3", 0)) >= 7
            and int(row.get("queryEdgeCount", 0)) >= 1800
            and float(row.get("medianPixels", 999.0)) <= 3.0
            and float(row.get("withinThreePixels", 0.0)) >= 0.55
        )
    except (TypeError, ValueError):
        return False


def _wide_translation_residual_has_strong_multiscale_support(
    residual: dict | None,
) -> bool:
    """Accept a dense current-frame wall field only with broad coverage."""
    row = residual if isinstance(residual, dict) else {}
    try:
        return bool(
            rendered_profile_residual_is_verified(row)
            and int(row.get("queryEdgeGridCells3x3", 0)) >= 7
            and int(row.get("queryEdgeCount", 0)) >= 8000
            and float(row.get("medianPixels", 999.0)) <= 3.0
            and float(row.get("withinThreePixels", 0.0)) >= 0.50
            and float(row.get("withinSixPixels", 0.0)) >= 0.65
            and float(row.get("explainedPixelFraction", 0.0)) >= 0.94
        )
    except (TypeError, ValueError):
        return False


def _canonical_wide_multiscale_evidence_is_consistent(
    refinement: dict | None,
) -> bool:
    """Combine a unique coarse peak with an agreeing independent fine pass."""
    row = refinement if isinstance(refinement, dict) else {}
    try:
        coarse_margin = float(row.get("translationDistinctMargin", 0.0))
        fine_margin = float(row.get("fineTranslationDistinctMargin", 0.0))
        coarse = np.asarray(
            row.get("coarseTranslationCorrection"), dtype=np.float64,
        )
        total = np.asarray(
            row.get("translationCorrection"), dtype=np.float64,
        )
        fine = np.asarray(
            row.get("fineTranslationCorrection"), dtype=np.float64,
        )
        return bool(
            coarse_margin >= 0.08
            and fine_margin >= 0.005
            and coarse.shape == (2,)
            and total.shape == (2,)
            and fine.shape == (2,)
            and np.isfinite(coarse).all()
            and np.isfinite(total).all()
            and np.isfinite(fine).all()
            and float(np.linalg.norm(total - coarse)) <= 3.0
            and float(np.linalg.norm(fine)) <= 3.0
        )
    except (TypeError, ValueError):
        return False


def wide_translation_search_is_unique(event: dict | None) -> bool:
    """Require unique evidence from the wide branch that was actually adopted."""
    row = event if isinstance(event, dict) else {}
    search_tier = str(row.get("searchTier") or "")
    if search_tier == "canonical-geometry-wide":
        refinement = row.get("canonicalGeometryWideRefinement")
        refinement = refinement if isinstance(refinement, dict) else {}
        margin = refinement.get("translationDistinctMargin", 0.0)
    elif search_tier == "target-floor-relation-wide":
        refinement = row.get("floorRelationRefinement")
        refinement = refinement if isinstance(refinement, dict) else {}
        if refinement.get("globalRecenterValidated") is not True:
            return False
        if not _wide_translation_residual_is_distributed(
            refinement.get("visualResidual")
        ):
            return False
        margin = refinement.get("distinctMargin", 0.0)
    else:
        return False
    residual = row.get("residual")
    try:
        margin_is_distinct = bool(
            float(margin) >= MINIMUM_WIDE_TRANSLATION_DISTINCT_MARGIN
        )
    except (TypeError, ValueError):
        margin_is_distinct = False
    standard_evidence = bool(
        margin_is_distinct
        and _wide_translation_residual_is_distributed(residual)
    )
    multiscale_evidence = bool(
        search_tier == "canonical-geometry-wide"
        and _canonical_wide_multiscale_evidence_is_consistent(refinement)
        and _wide_translation_residual_has_strong_multiscale_support(residual)
    )
    return bool(standard_evidence or multiscale_evidence)


def wide_translation_multiscale_same_frame_is_authorized(
    event: dict | None,
    latest_residual: dict | None,
) -> bool:
    """Authorize a B1 result from two-scale uniqueness plus a repeated gate."""
    row = event if isinstance(event, dict) else {}
    return bool(
        str(row.get("searchTier") or "") == "canonical-geometry-wide"
        and _canonical_wide_multiscale_evidence_is_consistent(
            row.get("canonicalGeometryWideRefinement")
        )
        and _wide_translation_residual_has_strong_multiscale_support(
            row.get("residual")
        )
        and _wide_translation_residual_has_strong_multiscale_support(
            latest_residual
        )
    )


def progressive_alignment_reason(
    change_score: float,
    alignment_in_progress: bool,
    alignment_succeeded: bool,
    elapsed_seconds: float,
    retry_seconds: float = 1.5,
    attempts: int = 0,
) -> str | None:
    """Retry weak localization, then wait for genuinely new map evidence."""
    if alignment_in_progress:
        return None
    if change_score >= 0.045 and elapsed_seconds >= retry_seconds:
        return "map-drift"
    if alignment_succeeded:
        return None
    retry_delay = retry_seconds * (1.0 if attempts <= 1 else 2.0 if attempts == 2 else 4.0)
    if attempts < 4 and elapsed_seconds >= retry_delay:
        return "progressive-retry"
    if attempts >= 4 and change_score >= 0.012 and elapsed_seconds >= retry_seconds * 2.0:
        return "progressive-retry"
    return None


def should_show_floating_fallback(
    map_is_open: bool,
    has_confirmed_map: bool,
    alignment_success: bool,
) -> bool:
    return bool(map_is_open and has_confirmed_map and not alignment_success)


def passive_map_probe_allowed(
    map_is_open: bool, predictive_mouse_drag: bool,
) -> bool:
    """Pause passive frames during drag; mouse-up schedules a fresh probe."""
    return bool(map_is_open and not predictive_mouse_drag)


ACTIVE_MAP_PROBE_INTERVAL_SECONDS = 0.06
STABLE_MAP_PROBE_INTERVAL_SECONDS = 0.12
CLOSED_MAP_PROBE_INTERVAL_SECONDS = 1.0
MOUSE_DRAG_SOURCE_REFRESH_IDLE_SECONDS = 0.05


def map_probe_interval_seconds(
    *,
    map_is_open: bool,
    alignment_succeeded: bool,
    overlay_visible: bool,
    correction_pending: bool,
    drag_active: bool,
) -> float:
    """Choose a bounded probe cadence without slowing map-open response.

    Recognition and recovery retain the existing 60 ms cadence. Once a
    verified route is visible and no correction or drag is active, the probe
    only needs to detect a close or a meaningful map change, so 120 ms halves
    full-frame capture pressure while remaining well below the one-second
    response contract. Closed state retains its cheap one-second heartbeat.
    """
    if not map_is_open:
        return CLOSED_MAP_PROBE_INTERVAL_SECONDS
    if (
        alignment_succeeded
        and overlay_visible
        and not correction_pending
        and not drag_active
    ):
        return STABLE_MAP_PROBE_INTERVAL_SECONDS
    return ACTIVE_MAP_PROBE_INTERVAL_SECONDS


def map_probe_close_is_precommit_or_too_early(
    probe_open: bool | None,
    probe_display_epoch: int,
    current_display_epoch: int,
    captured_at: float,
    verified_at: float,
    *,
    now: float | None = None,
    grace_seconds: float = 0.25,
) -> bool:
    """Reject false probes that cannot describe the newly committed overlay."""
    if probe_open is not False or verified_at <= 0.0:
        return False
    current_time = time.monotonic() if now is None else float(now)
    return bool(
        int(probe_display_epoch) != int(current_display_epoch)
        or float(captured_at) < float(verified_at)
        or current_time - float(verified_at) < float(grace_seconds)
    )


def window_process_id(hwnd: int | None) -> int | None:
    if not hwnd:
        return None
    process_id = ctypes.c_ulong(0)
    ctypes.windll.user32.GetWindowThreadProcessId(
        int(hwnd), ctypes.byref(process_id),
    )
    return int(process_id.value) or None


def alignment_transform_is_similar(
    first: list[list[float]] | np.ndarray | None,
    second: list[list[float]] | np.ndarray | None,
    *,
    scale_tolerance: float = 0.035,
    rotation_tolerance_degrees: float = 2.5,
    translation_tolerance_pixels: float = 64.0,
) -> bool:
    """Compare displayed similarity transforms for same-round rejection vetoes."""
    try:
        left = np.asarray(first, dtype=np.float64)
        right = np.asarray(second, dtype=np.float64)
    except (TypeError, ValueError):
        return False
    if (
        left.shape != (3, 3) or right.shape != (3, 3)
        or not np.isfinite(left).all() or not np.isfinite(right).all()
    ):
        return False
    left_scale = float(np.sqrt(abs(np.linalg.det(left[:2, :2]))))
    right_scale = float(np.sqrt(abs(np.linalg.det(right[:2, :2]))))
    if min(left_scale, right_scale) <= 1e-6:
        return False
    scale_delta = abs(left_scale / right_scale - 1.0)
    left_rotation = float(np.degrees(np.arctan2(left[1, 0], left[0, 0])))
    right_rotation = float(np.degrees(np.arctan2(right[1, 0], right[0, 0])))
    rotation_delta = abs((left_rotation - right_rotation + 180.0) % 360.0 - 180.0)
    translation_delta = float(np.linalg.norm(left[:2, 2] - right[:2, 2]))
    return bool(
        scale_delta <= scale_tolerance
        and rotation_delta <= rotation_tolerance_degrees
        and translation_delta <= translation_tolerance_pixels
    )


def reusable_manual_confirmation(
    remembered_map_id: str | None,
    ranked: list[dict],
    map_is_open: bool,
    floor_required: bool,
) -> str | None:
    """An explicit round lock outranks the advisory shortlist until round end."""
    if not remembered_map_id or not map_is_open or floor_required:
        return None
    return remembered_map_id


def should_auto_lock_candidate(
    top: dict | None,
    floor_required: bool,
    existing_confirmation: str | None,
) -> bool:
    """Only an explicit multi-evidence identity gate may replace the first click.

    An automatic lock is round state, not a training label. If the player
    corrects it, the explicit confirmation becomes the remembered truth.
    """
    return bool(
        isinstance(top, dict)
        and top.get("mapId")
        and top.get("strongSuggestion")
        and top.get("identityHardGatePassed")
        and not floor_required
        and not existing_confirmation
    )


def scaled_sheet_max_size(scale: float) -> tuple[int, int]:
    bounded = min(1.50, max(0.50, float(scale)))
    return round(330 * bounded), round(400 * bounded)


def left_candidate_panel_geometry(
    screen_width: int,
    screen_height: int,
) -> tuple[int, int, int, int]:
    """Fit the fallback picker wholly inside the screen's left half."""
    width = max(int(screen_width), 1)
    height = max(int(screen_height), 1)
    margin = max(8, min(24, width // 40, height // 40))
    available_width = max(240, width // 2 - margin * 2)
    available_height = max(360, height - margin * 2)
    # The manual fallback is a narrow candidate rail, not a settings dashboard.
    # Keep it readable at 720p while leaving most of the map unobstructed.
    panel_width = min(440, available_width)
    panel_height = min(640, available_height)
    x = margin
    y = max(margin, (height - panel_height) // 2)
    return int(panel_width), int(panel_height), int(x), int(y)


def docked_orb_position(
    x: int,
    y: int,
    width: int,
    height: int,
    work_area: tuple[int, int, int, int],
    *,
    edge: str | None = None,
    ratio: float | None = None,
    margin: int = 12,
) -> tuple[int, int, str, float]:
    """Place an orb on one safe edge and return its normalized edge offset."""
    left, top, right, bottom = (int(value) for value in work_area)
    width = max(1, int(width))
    height = max(1, int(height))
    margin = max(0, int(margin))
    min_x = left + margin
    max_x = max(min_x, right - width - margin)
    min_y = top + margin
    max_y = max(min_y, bottom - height - margin)
    clamped_x = max(min_x, min(int(x), max_x))
    clamped_y = max(min_y, min(int(y), max_y))
    allowed_edges = {"left", "right", "top", "bottom"}
    if edge not in allowed_edges:
        distances = {
            "left": abs(clamped_x - min_x),
            "right": abs(max_x - clamped_x),
            "top": abs(clamped_y - min_y),
            "bottom": abs(max_y - clamped_y),
        }
        edge = min(distances, key=distances.get)
    if ratio is not None:
        bounded_ratio = max(0.0, min(float(ratio), 1.0))
        if edge in {"left", "right"}:
            clamped_y = round(min_y + (max_y - min_y) * bounded_ratio)
        else:
            clamped_x = round(min_x + (max_x - min_x) * bounded_ratio)
    if edge == "left":
        clamped_x = min_x
    elif edge == "right":
        clamped_x = max_x
    elif edge == "top":
        clamped_y = min_y
    else:
        clamped_y = max_y
    span = (max_y - min_y) if edge in {"left", "right"} else (max_x - min_x)
    offset = (clamped_y - min_y) if edge in {"left", "right"} else (clamped_x - min_x)
    normalized = float(offset / span) if span > 0 else 0.5
    return int(clamped_x), int(clamped_y), str(edge), normalized


def adjacent_quick_panel_geometry(
    orb_bounds: tuple[int, int, int, int],
    panel_size: tuple[int, int],
    work_area: tuple[int, int, int, int],
    *,
    preferred_edge: str | None = None,
    gap: int = 10,
    margin: int = 8,
) -> tuple[int, int]:
    """Place the quick panel beside the orb and keep it inside one monitor."""
    orb_x, orb_y, orb_width, orb_height = (int(value) for value in orb_bounds)
    panel_width, panel_height = (max(1, int(value)) for value in panel_size)
    left, top, right, bottom = (int(value) for value in work_area)
    min_x, min_y = left + margin, top + margin
    max_x = max(min_x, right - panel_width - margin)
    max_y = max(min_y, bottom - panel_height - margin)
    room_right = right - (orb_x + orb_width)
    room_left = orb_x - left
    place_left = preferred_edge == "right" or (
        preferred_edge not in {"left", "right"} and room_left > room_right
    )
    x = orb_x - panel_width - gap if place_left else orb_x + orb_width + gap
    y = orb_y + (orb_height - panel_height) // 2
    return (
        max(min_x, min(int(x), max_x)),
        max(min_y, min(int(y), max_y)),
    )


def floating_status_color(color: str) -> str:
    """Present existing semantic colors on light surfaces without changing facts."""
    return {
        "#5ee0a3": floating_theme.GREEN,
        "#93c5fd": floating_theme.PRIMARY_HOVER,
        "#94a3b8": floating_theme.MUTED,
        "#f6c453": floating_theme.GOLD,
        "#ff8a65": floating_theme.ERROR,
        "#ffb84d": floating_theme.GOLD,
    }.get(color, color)


def semantic_orb_state(status_text: str, round_locked: bool = False) -> tuple[str, str]:
    """Map detailed panel copy to a compact non-color-only orb state."""
    text = str(status_text or "")
    if any(word in text for word in ("失败", "错误", "缺失", "异常")):
        return "错", "发生异常"
    if "显示环境" in text and "超出已验证范围" in text:
        return "选", "显示环境未验收 · 可继续使用"
    if any(word in text for word in (
        "请点", "请选择", "请先", "候选", "已选", "楼层不明", "需要确认",
        "自动证据不足", "锁定暂不可用", "可能是新一局",
    )):
        return "选", "需要操作"
    if round_locked and any(word in text for word in (
        "正在验证", "正在重新", "正在校正", "重新定位", "精定位",
        "地图位置变化", "地图位置已变化", "平移未收敛",
    )):
        return "锁", "本局已锁定 · 正在校准"
    if any(word in text for word in (
        "正在识别", "自动识别地图中", "检测地图中", "正在验证", "正在重新",
        "正在校正", "自动监听启动",
        "地图位置变化", "预加载",
    )):
        return "识", "正在识别"
    if round_locked or any(word in text for word in (
        "本局已锁定", "本局地图已确认", "本局沿用",
        "小抄已贴合", "同局将自动复用",
    )):
        return "锁", "本局已锁定"
    return "待", "等待开图"


